BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('dca-q82', 'Orchestration',
   'Swarmサービスの再起動ポリシー（--restart-condition）で、タスクが異常終了したときだけ再起動させたい。正しい指定はどれか。',
   NULL::text,
   '["--restart-condition on-failure", "--restart-condition always", "--restart-condition unless-stopped", "--restart-condition on-exit"]',
   0,
   '[0]',
   'single',
   '{"asked": "restart-conditionの3種類の使い分けを理解しているか。", "point": "異常終了時だけ再起動するなら on-failure。", "kid": "コンテナが終了したときに、Swarmが自動で作り直すかどうかの条件を決める設定。", "eg": "自動販売機が壊れたときだけ係員を呼ぶ（on-failure）。正常に売り切れて止まった機械までは呼ばない。", "terms": [["on-failure", "終了コードが0以外（異常終了）のときだけ再起動する。"], ["restart-condition", "docker service create/update のフラグ。none/on-failure/anyの3値。"]], "think": "なぜ条件を分けるのかがカギ。always相当の挙動（常に再起動）だと、意図的に停止させたタスクまで復活してしまい制御できない。on-failureは終了コードを見て『異常終了のときだけ』作り直すので、正常終了と障害を区別できる。", "vs": "Swarmのrestart-conditionは none/on-failure/any の3値のみ。docker run --restart で使う always や unless-stopped はスタンドアロンコンテナ向けのオプションで、Swarmサービスのrestart-conditionには存在しない。", "usecase": "バッチジョブ系のサービスで、失敗したときだけ自動リトライさせたいときに使う。", "opt": ["正解。終了コードが異常（0以外）のときだけ再起動する。", "Swarmのrestart-conditionにalwaysという値は無い（noneなら再起動しない）。", "unless-stoppedはdocker runのフラグで、Swarmのrestart-conditionには存在しない。", "on-exitという値もSwarmのrestart-conditionには存在しない。"]}'),

  ('dca-q83', 'Orchestration',
   'Swarmサービスのローリングアップデートで、途中のタスクが失敗し続けた場合の挙動を決める設定はどれか。',
   NULL::text,
   '["--update-failure-action", "--update-parallelism", "--update-delay", "--update-order"]',
   0,
   '[0]',
   'single',
   '{"asked": "更新失敗時の挙動を制御する設定を知っているか。", "point": "更新失敗時にどうするかは --update-failure-action（pause/continue/rollback）。", "kid": "新バージョンへの入れ替え中にタスクが立ち上がらないとき、そこで止めるか、無視して続けるか、前のバージョンに戻すかを決める設定。", "eg": "リフォーム中に不具合が出たら、そこで工事を止める（pause）か、気にせず次の部屋も工事する（continue）か、元の状態に戻す（rollback）か。", "terms": [["update-failure-action", "pause（既定・一時停止して人の判断を待つ）/continue（無視して進める）/rollback（自動で前の状態に戻す）"]], "think": "なぜ既定はpauseなのかがカギ。continueのまま突き進むと、壊れた新バージョンが次々に配られて被害が広がる。かといって毎回自動rollbackだと、一時的なネットワーク遅延のような偽陽性でも巻き戻ってしまう。だから既定は『いったん止めて人が判断する』pauseにしてある。", "vs": "update-parallelismは同時に何個ずつ入れ替えるか、update-delayは入れ替え間隔、update-orderは新を先に起動するか旧を先に止めるか（start-first/stop-first）。いずれも『失敗したときどうするか』は決めない。", "usecase": "本番アップデートで、失敗を検知したら自動的に前のバージョンへ戻したいときは rollback を指定する。", "opt": ["正解。pause（既定）/continue/rollbackの3値で失敗時の挙動を決める。", "parallelismは同時に入れ替えるタスク数を決めるだけで、失敗時の挙動は制御しない。", "delayは各バッチの間隔（待ち時間）を決めるだけで、失敗時の挙動は制御しない。", "orderは新旧どちらを先に処理するかを決めるだけで、失敗時の挙動は制御しない。"], "viz": "<svg viewBox=\"0 0 340 172\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">ローリングアップデート失敗時の3つの挙動</text><rect x=\"8\" y=\"30\" width=\"104\" height=\"20\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"60.0\" y=\"44\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"600\">pause（既定）</text><text x=\"60.0\" y=\"66\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">失敗を検知したら</text><text x=\"60.0\" y=\"78\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そこで一時停止</text><text x=\"60.0\" y=\"90\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">人の判断を待つ</text><rect x=\"120\" y=\"30\" width=\"104\" height=\"20\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#60a5fa\" stroke-width=\"1\"/><text x=\"172.0\" y=\"44\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">continue</text><text x=\"172.0\" y=\"66\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">失敗を無視して</text><text x=\"172.0\" y=\"78\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">次のバッチへ</text><text x=\"172.0\" y=\"90\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのまま進む</text><rect x=\"232\" y=\"30\" width=\"104\" height=\"20\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"284.0\" y=\"44\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">rollback</text><text x=\"284.0\" y=\"66\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自動で前の</text><text x=\"284.0\" y=\"78\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">バージョンへ</text><text x=\"284.0\" y=\"90\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">巻き戻す</text><text x=\"170\" y=\"118\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">既定がpauseな理由: continueだと壊れた版が広がり、</text><text x=\"170\" y=\"130\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自動rollbackだと一時的な誤検知でも巻き戻ってしまう</text><text x=\"170\" y=\"152\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">--update-failure-action で切り替える</text></svg>"}'),

  ('dca-q84', 'Orchestration',
   'Swarmにワーカーノードを新規参加させるための docker swarm join-token worker で得られるトークンについて正しい説明はどれか。',
   NULL::text,
   '["マネージャートークンとは別の値で、ワーカーとしての参加権限しか持たない", "マネージャートークンと全く同じ値が使われる", "トークンは参加のたびに毎回自動生成され、使い回せない", "トークンはSwarm全体を削除できる権限を含む"]',
   0,
   '[0]',
   'single',
   '{"asked": "worker用とmanager用のjoin-tokenが別物で、権限も別であることを理解しているか。", "point": "workerトークンとmanagerトークンは別の値で、それぞれ持てる権限が違う。", "kid": "Swarmに新しいノードを参加させるための合言葉（トークン）。ワーカー用とマネージャー用で別の合言葉があり、渡す相手によって使い分ける。", "eg": "会社の入館証に「一般社員用」と「役員用」で別のカードがあるようなもの。役員用カードを一般社員に渡すと権限が強すぎて危険。", "terms": [["join-token worker", "ワーカーとしてのみ参加できるトークン。クラスターの管理操作はできない。"], ["join-token manager", "マネージャーとして参加できるトークン。クラスターの制御権限を持つため厳重管理が要る。"]], "think": "なぜ2種類に分けるのかがカギ。もしトークンが1種類しかなければ、ワーカーとして雇いたいだけのマシンにも管理者権限が渡ってしまう。トークンを役割ごとに分けることで、『参加させたいが管理はさせたくない』ノードにはworkerトークンだけを渡せる。managerトークンが漏れるとクラスターを乗っ取られるので、workerトークンより厳重に扱う。", "vs": "同じ値ではない。トークンはswarm initやswarm join-token --rotateをしない限り使い回せる（毎回変わるわけではない）。トークン自体にSwarm削除権限は無い（削除はswarm leave --forceやマネージャー操作で行う）。", "usecase": "新しいマシンをSwarmクラスターに参加させるとき、そのマシンにワーカーだけをさせたいならworkerトークンをコピーして docker swarm join で使う。", "opt": ["正解。workerとmanagerでトークンの値も権限も別。", "workerトークンとmanagerトークンは別の値。同じではない。", "トークンはswarm initの時点で発行され、明示的にrotateしない限り使い回せる。", "トークンはノード参加の認証にのみ使う。Swarm全体の削除権限は含まない。"]}'),

  ('dca-q85', 'Orchestration',
   'Swarmサービスのタスクに接続するとき、既定のendpoint-mode（VIP）でクライアントが受け取るのはどれか。',
   NULL::text,
   '["サービス全体を代表する仮想IP（VIP）1つで、内部で各タスクへ振り分けられる", "動いているタスクの数だけ実IPアドレスがDNS応答で返る", "常に最初に起動したタスクの実IPだけが返る", "接続のたびにマネージャーへ問い合わせて手動でIPを選ぶ必要がある"]',
   0,
   '[0]',
   'single',
   '{"asked": "Swarmサービスの既定のロードバランシング方式（VIP）を理解しているか。", "point": "既定のendpoint-modeはVIP：サービス名を引くと仮想IP1つが返り、その先で複数タスクに自動分散される。", "kid": "サービスにアクセスするとき、実際に動いているコンテナのIPを1つ1つ意識しなくていい。窓口となる1つの仮想IPだけ知っていれば、その奥で自動的にタスクへ振り分けてくれる。", "eg": "会社の代表電話番号にかけると、内線がどの担当者につながるかは交換機が自動で決めてくれる。かける側は代表番号だけ知っていればいい。", "terms": [["VIP (Virtual IP)", "サービスに割り当てられる仮想IP。既定のendpoint-mode。IPVSでタスクへ負荷分散する。"], ["DNSRR (DNS Round Robin)", "endpoint-mode dnsrrを指定した場合の代替方式。DNS応答で各タスクの実IPを順番に返す。"]], "think": "なぜ仮想IP1つにまとめるのかがカギ。タスクは健康チェック失敗やスケールで数が増減する。もしクライアント側が個々のタスクIPを直接覚えていたら、その都度アプリ側でIPリストを更新し直さないといけない。VIPなら窓口のアドレスは変わらず、奥の実タスクの入れ替えはSwarm側が吸収してくれる。", "vs": "DNSRRを明示的に指定した場合だけ、複数の実IPがDNS応答として返る（クライアント側でどれを使うか選ぶ必要が出る）。既定はVIPなのでこの動作にはならない。", "usecase": "特にDNSクライアント側のキャッシュ挙動が問題になる場合を除き、既定のVIPのままにしておけばSwarmが分散を面倒見てくれる。", "opt": ["正解。既定はVIP。仮想IP1つの奥でIPVSベースの分散が行われる。", "この動きはendpoint-mode dnsrrを明示指定した場合の話で、既定（VIP）ではない。", "最初のタスクだけに固定されることはない。VIPの奥では複数タスクに分散される。", "手動でIPを選ぶ操作は不要。VIP宛の接続はSwarm側が自動で分散する。"], "viz": "<svg viewBox=\"0 0 340 168\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">VIP（既定）：窓口は1つ、奥で自動分散</text><rect x=\"120\" y=\"28\" width=\"100\" height=\"22\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"43\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービス名を引く</text><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"64\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><rect x=\"120\" y=\"66\" width=\"100\" height=\"22\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"81\" font-size=\"8\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">仮想IP 1つ (VIP)</text><line x1=\"170\" y1=\"88\" x2=\"70\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"30\" y=\"100\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"70\" y=\"113\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">タスク1</text><line x1=\"170\" y1=\"88\" x2=\"160\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"120\" y=\"100\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"160\" y=\"113\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">タスク2</text><line x1=\"170\" y1=\"88\" x2=\"250\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"210\" y=\"100\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"250\" y=\"113\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">タスク3</text><text x=\"170\" y=\"140\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">dnsrr指定時だけ、複数の実IPがそのままDNS応答で返る</text><text x=\"170\" y=\"153\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（クライアント側でどれを使うか選ぶ必要が出る）</text></svg>"}'),

  ('dca-q86', 'Orchestration',
   'docker service create --reserve-memory 512m --limit-memory 1g の意味として正しいものはどれか。',
   NULL::text,
   '["512MBはスケジューリング時に確保する目安、1GBは実行時にそれ以上使わせない上限", "512MBが上限で1GBが目安、reserveとlimitの意味が逆になっている", "両方とも同じ意味を持つ設定で、後に書いた方だけが有効になる", "reserveはスケジューラに一切使われず、limitの値だけが唯一有効になる"]',
   0,
   '[0]',
   'single',
   '{"asked": "reserveとlimitという似た2つのメモリ設定の役割の違いを理解しているか。", "point": "reserveは配置先を決めるときの『これだけ空きが要る』という目安、limitは実行中の『これ以上は使わせない』という上限。", "kid": "reserveは「このノードに置いてよいか判断するための最低ライン」、limitは「動いているときに実際に使ってよい最大量」。似た名前だが役割が違う。", "eg": "reserveは引っ越し先を選ぶときの『最低このくらいの広さの部屋が必要』という条件、limitは住み始めてからの『契約アンペア（電気の上限）』。", "terms": [["--reserve-memory", "スケジューラがノードへタスクを配置する際に考慮する、確保しておきたいメモリの目安。"], ["--limit-memory", "実行中のコンテナが実際に使えるメモリの上限。超えるとOOM Killされる。"]], "think": "なぜ2つに分かれているのかがカギ。reserveだけだと『空きがあるノードに置く』ことはできても、動き出してから使いすぎるのを止められない。limitだけだと、配置時に空きが足りないノードに詰め込まれてしまうかもしれない。reserveで『置き場所選び』を、limitで『動いてからの上限』を、それぞれ別の場面で使い分けている。", "vs": "順番が逆ではない。reserveは配置判断用の目安であって強制的な上限ではなく、limitはOOM Killを伴う実行時の強制上限。両方指定した場合、どちらも独立して効く（片方が無視されることはない）。", "usecase": "リソースが逼迫したクラスターで、確実に空きのあるノードに配置しつつ、暴走するプロセスの被害を上限で抑えたいときに両方指定する。", "opt": ["正解。reserveは配置時の目安、limitは実行時の強制上限。", "説明が逆。reserveが上限でlimitが目安、ではない。", "同じ意味ではない。役割が異なるため両方が意味を持つ。", "reserveも無視されず、スケジューラの配置判断に使われる。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.3\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">reserve＝配置の目安、limit＝実行時の上限</text><rect x=\"15\" y=\"30\" width=\"145\" height=\"46\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"87.5\" y=\"44\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"600\">--reserve-memory</text><text x=\"87.5\" y=\"58\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">配置先を選ぶときの</text><text x=\"87.5\" y=\"69\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">『これだけ空きが要る』目安</text><rect x=\"180\" y=\"30\" width=\"145\" height=\"46\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"252.5\" y=\"44\" font-size=\"8.5\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"600\">--limit-memory</text><text x=\"252.5\" y=\"58\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行中に『これ以上</text><text x=\"252.5\" y=\"69\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">使わせない』強制上限</text><text x=\"170\" y=\"100\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">reserveだけ→空きノードには置けても使いすぎを止められない</text><text x=\"170\" y=\"113\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">limitだけ→配置時に空きが足りないノードに詰め込まれうる</text><text x=\"170\" y=\"134\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">だから場面ごとに役割を分けている</text></svg>"}'),

  ('dca-q87', 'Orchestration',
   'docker node ls の出力から確認できる情報として正しいものはどれか。',
   NULL::text,
   '["各ノードの役割（Manager/Worker）・可用性（Active/Drain）・リーダーかどうか", "各サービスに割り当てられているレプリカ数と、それぞれのヘルスステータス", "各コンテナが実行中に使用しているCPU・メモリの実使用量の推移", "各イメージが持つ全レイヤーの構成サイズと、ビルドされた日時"]',
   0,
   '[0]',
   'single',
   '{"asked": "docker node ls で見えるのはクラスターのノード一覧であって、サービスやコンテナの詳細ではないと理解しているか。", "point": "node lsはノード（マシン）の一覧。役割・可用性・リーダーの印が見える。", "kid": "Swarmクラスターに参加しているマシン（ノード）を一覧表示するコマンド。誰がマネージャーで誰がワーカーか、今どのマネージャーがリーダーかが見える。", "eg": "会社の組織図を見るようなもの。誰が管理職（マネージャー）で誰が一般社員（ワーカー）かが一目でわかる。", "terms": [["Leader", "複数マネージャーのうち、Raftで選ばれた実際に書き込みを行う代表。node ls の MANAGER STATUS 列に *付きで表示。"], ["Availability", "Active（タスク配置可）/Pause（新規停止）/Drain（退避＋新規停止）の3状態。"]], "think": "node lsは『どのマシンがクラスターにいて、それぞれ何の役割か』を見るためのコマンド。サービスの中身（レプリカ数やコンテナのリソース使用量）はservice lsやdocker statsなど別のコマンドの守備範囲。", "vs": "サービスのレプリカ数・ヘルスは docker service ls / ps で見る。コンテナの実使用量は docker stats。イメージのレイヤー情報は docker image history や inspect。node lsはあくまでノード単位の情報。", "usecase": "マネージャーが何台生きているか、どのノードがdrain中かを確認するときにまず打つコマンド。", "opt": ["正解。ノードの役割・可用性・リーダーの印を一覧できる。", "サービス単位のレプリカ数やヘルスは docker service ls/ps で見る情報。", "コンテナのリアルタイムCPU/メモリ使用量は docker stats で見る情報。", "イメージのレイヤー情報は docker image history や inspect で見る情報。"]}'),

  ('dca-q88', 'Orchestration',
   'docker swarm init --autolock を有効にした場合の効果として正しいものはどれか。',
   NULL::text,
   '["マネージャーのRaftデータが暗号化され、再起動時にアンロックキーの入力が必要になる", "ワーカーノードがSwarmに参加する際に必ずパスワードを求められる", "全サービスの通信がTLSで自動的に暗号化される", "サービスのイメージが自動的にDocker Content Trustで署名される"]',
   0,
   '[0]',
   'single',
   '{"asked": "autolockが守るのはRaftのディスク上データであって、通信や参加プロセスではないと理解しているか。", "point": "autolockはマネージャーのRaftデータをディスク上で暗号化し、再起動時にアンロックキーを要求する機能。", "kid": "マネージャーが管理しているクラスターの状態（Raftログ）を、ディスクに保存するときに鍵をかける機能。マネージャーが再起動したら、その鍵（アンロックキー）を入力しないと復旧しない。", "eg": "金庫に入れた書類は、金庫ごと盗まれても鍵（アンロックキー）が無ければ中身を読めない。", "terms": [["autolock", "マネージャーのRaftデータをディスク上で暗号化するSwarmの機能。docker swarm unlock でアンロックキーを入力して復旧する。"], ["Raftデータ", "クラスターの状態（サービス定義・secret等）を記録した合意ログ。マネージャーのディスクに保存される。"]], "think": "なぜロックするのかがカギ。マネージャーのディスクにはsecretなどの機密情報を含むRaftログがそのまま保存されている。もしそのディスク（や中古のハードディスク）が盗まれたら、暗号化していないと中身をそのまま読み取られてしまう。autolockを有効にすると、ディスク上のデータ自体が暗号化され、正しいアンロックキーを知らない限り読めない。", "vs": "ノード間の通信は既定でTLSにより暗号化されており、autolockとは別の仕組み（autolockはディスク上データの暗号化）。ワーカー参加時のパスワード入力とも無関係（参加はjoin-tokenで行う）。イメージ署名はDocker Content Trustの役割で、autolockとは無関係。", "usecase": "マネージャーノードの物理的な盗難・持ち出しリスクがある環境で、ディスク上のクラスター機密情報を守りたいときに有効にする。", "opt": ["正解。Raftデータをディスク上で暗号化し、再起動時にアンロックキーを要求する。", "ワーカー参加はjoin-tokenで行われ、autolockとは無関係。", "通信のTLS暗号化はSwarムの既定動作であり、autolock特有の効果ではない。", "イメージの署名はDocker Content Trustの役割で、autolockとは無関係。"]}'),

  ('dca-q89', 'Image Creation, Management, and Registry',
   'Dockerfileの LABEL 命令の主な役割はどれか。',
   NULL::text,
   '["イメージにバージョンや作成者などのメタデータをキー・バリューで埋め込む", "コンテナ起動時に自動でラベルというタグを外部に公開する", "イメージのレイヤーに名前（ラベル）を付けてキャッシュを固定する", "ビルド時に使う変数にラベルという別名を付ける"]',
   0,
   '[0]',
   'single',
   '{"asked": "LABEL命令がイメージに付随する説明書きであり、動作に影響しないメタデータだと理解しているか。", "point": "LABELはイメージに付ける説明書き（メタデータ）。動作には関係しない。", "kid": "イメージに「誰が作ったか」「バージョンはいくつか」のようなラベル（付箋）を貼っておく命令。中身の動きには影響しない。", "eg": "荷物に貼る宛名シール。中身の商品自体は変わらないが、あとで見た人が情報を読み取れる。", "terms": [["LABEL", "LABEL key=\"value\" の形でイメージのメタデータを埋め込むDockerfile命令。docker image inspectで確認できる。"]], "think": "なぜ動作に影響しないのかがカギ。LABELはイメージのメタデータ領域に書き込まれるだけで、コンテナ内で実行されるプロセスやファイルシステムには一切関与しない。docker image inspectで後から読み取れる『付箋』であり、CI/CDやツールが「このイメージは誰が作ったか」を機械的に判断するのに使われる。", "vs": "外部への自動公開のような能動的な動作はしない（inspectで見る側が能動的に読む）。レイヤーキャッシュの固定とは無関係（キャッシュはCOPY/RUNなど命令の内容で決まる）。ビルド変数の別名でもない（それはARGの役割）。", "usecase": "maintainer情報やGitのコミットハッシュ、ビルド日時などをイメージに埋め込み、後から「このイメージはどのソースから作られたか」を追跡するのに使う。", "opt": ["正解。バージョンや作成者などのメタデータをキー・バリューで埋め込む。", "外部への自動公開のような能動的な動作はしない。", "レイヤーキャッシュの固定とは無関係。キャッシュは命令の内容で決まる。", "ビルド変数の別名を付ける機能ではない。それはARGの役割。"]}'),

  ('dca-q90', 'Image Creation, Management, and Registry',
   'Dockerfileの ONBUILD 命令の動作として正しいものはどれか。',
   NULL::text,
   '["このイメージをFROMで使う別のDockerfileがビルドされるときに、指定した命令が実行される", "そのイメージのビルドが完了した直後に、自動的にコンテナが1つ起動される", "そのイメージ自身のビルドが失敗したときだけ、指定した命令が実行される", "ビルドキャッシュを無視して、指定した命令が常に再実行される"]',
   0,
   '[0]',
   'single',
   '{"asked": "ONBUILDが『自分自身のビルド時』ではなく『自分を親にした子ビルド時』に発火するトリガーだと理解しているか。", "point": "ONBUILDは自分のビルド時ではなく、自分をFROMで使う子イメージのビルド時に発火する。", "kid": "「このイメージを土台にして誰かが新しいイメージを作るとき、その時になったらこの命令をやってね」という予約命令。自分自身がビルドされるときには何も起きない。", "eg": "先生が黒板に「次にこの教室を使う人はこれをやってください」と書き置きを残す。書いた本人が今すぐやるわけではなく、次に使う人が実行する。", "terms": [["ONBUILD", "ONBUILD <命令> の形で、子イメージのビルド時に実行される命令を予約するDockerfile命令。"], ["ベースイメージ", "FROMで指定される、ビルドの土台となるイメージ。"]], "think": "なぜ『自分のビルド時』ではなく『子のビルド時』に発火させるのかがカギ。言語ランタイムなどの共通ベースイメージを作る側は、実際のアプリのソースコードをまだ持っていない。ONBUILDで「子がFROMしたら、その時点のソースをCOPYしてビルドしてね」と予約しておくことで、ベースイメージ自体は空のままでも、それを使う側のビルド時に自動でアプリ固有の処理を挟み込める。", "vs": "自動でコンテナが起動するわけではない（それはCMD/ENTRYPOINTの役割で、しかもdocker run時）。ビルド失敗時のフォールバックでもない。キャッシュの扱いは通常の命令と同様（内容が変われば無効化される）。", "usecase": "言語別の共通ベースイメージ（例: 「依存関係をインストールしてからソースをコピーする」という定型作業）を用意し、各プロジェクトのDockerfileを短く保ちたいときに使う。", "opt": ["正解。自分をFROMで使う子イメージのビルド時に発火するトリガー。", "自動でコンテナが起動する動作はしない。それはビルド後のdocker runの話。", "ビルド失敗時限定の動作ではない。", "キャッシュの扱いは他の命令と同様で、常に再実行されるわけではない。"], "viz": "<svg viewBox=\"0 0 340 168\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">ONBUILD：自分のビルド時は眠ったまま</text><rect x=\"15\" y=\"30\" width=\"140\" height=\"60\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"85\" y=\"44\" font-size=\"8.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"600\">ベースイメージ</text><rect x=\"25\" y=\"54\" width=\"120\" height=\"20\" rx=\"4\" fill=\"#2a2416\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"85\" y=\"67\" font-size=\"7.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">ONBUILD COPY ...</text><text x=\"85\" y=\"82\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">このビルドでは発火しない</text><line x1=\"155\" y1=\"60\" x2=\"185\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"54\" font-size=\"7\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">FROM</text><rect x=\"185\" y=\"30\" width=\"140\" height=\"60\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255\" y=\"44\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">子イメージのビルド</text><rect x=\"195\" y=\"54\" width=\"120\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255\" y=\"67\" font-size=\"7.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">予約命令が今ここで発火</text><text x=\"255\" y=\"82\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ソースをCOPYして実行</text><text x=\"170\" y=\"118\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">黒板の『次の人はこれをやって』という書き置きと同じ。</text><text x=\"170\" y=\"131\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">書いた本人ではなく、次に使う人が実行する</text></svg>"}'),

  ('dca-q91', 'Image Creation, Management, and Registry',
   'Dockerfileの EXPOSE 命令と docker run -p の違いとして正しいものはどれか。',
   NULL::text,
   '["EXPOSEはどのポートを使う想定かの申告（ドキュメント）で、実際に外部公開するのは -p", "EXPOSEを書けば自動的にホストへポートが公開される", "-pを付けなくても、EXPOSEだけで外部からアクセスできる", "EXPOSEと-pは同じ効果で、片方だけ書けば十分"]',
   0,
   '[0]',
   'single',
   '{"asked": "EXPOSEが実際の公開を行わない、あくまで申告（ドキュメント）だと理解しているか。", "point": "EXPOSEは『このポートを使う想定』の申告にすぎない。実際に外へ開けるのは docker run -p。", "kid": "EXPOSEはDockerfileに書く「このコンテナは8080番を使いますよ」という案内書き。実際にホストの外から届くようにするのは、起動時の -p オプションの役目。", "eg": "建物の案内板に「3階に会議室があります」と書いてあっても、実際にその階のドアが開いていないと入れない。EXPOSEは案内板、-pがドアを開ける操作。", "terms": [["EXPOSE", "Dockerfile内でコンテナが使うポート番号を宣言する命令。ドキュメント目的で、公開自体は行わない。"], ["-p (--publish)", "docker run時にホストのポートとコンテナのポートを実際に結びつけるオプション。"]], "think": "なぜ2段階に分かれているのかがカギ。イメージを作る人（Dockerfile作者）と、それを動かす人（docker run実行者）は別人であることが多い。EXPOSEは作者が『このイメージはこのポートで待ち受けています』と伝えるための情報にすぎず、実際に外部からアクセスできるようにするかどうかの最終判断（セキュリティ上の公開・非公開）は、動かす人が -p や -P で決める。", "vs": "EXPOSEだけでは外部公開されない（docker run -Pを使えばEXPOSEされた全ポートがランダムなホストポートに自動割り当てされるが、これも-Pという明示操作が要る）。EXPOSEと-pは役割が異なり、どちらか一方で十分ということはない。", "usecase": "Dockerfileを配布する側が「このイメージは何番ポートを想定しているか」を明示し、使う側が -p で実際の公開可否とマッピングを決める、という役割分担に使われる。", "opt": ["正解。EXPOSEは申告のみ、実際の公開は-pが行う。", "EXPOSEだけでは自動公開されない。", "-pなしでは外部からアクセスできない（-Pなら別）。", "役割が異なるため、片方だけで足りるわけではない。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">EXPOSEは申告、-pが実際に開ける</text><rect x=\"20\" y=\"30\" width=\"140\" height=\"40\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"90\" y=\"46\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"600\">EXPOSE 8080</text><text x=\"90\" y=\"60\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「使う想定」の案内板のみ</text><rect x=\"180\" y=\"30\" width=\"140\" height=\"40\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"250\" y=\"46\" font-size=\"7.8\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">docker run -p 8080:8080</text><text x=\"250\" y=\"60\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実際にホストへ穴を開ける</text><text x=\"170\" y=\"90\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">案内板だけ見ても、ドアが開いていなければ入れない</text><text x=\"170\" y=\"112\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">EXPOSEだけでは外部から未到達。</text><text x=\"170\" y=\"125\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">-p（または-P）を付けて初めて外に開く</text></svg>"}'),

  ('dca-q92', 'Image Creation, Management, and Registry',
   'Dockerfileの VOLUME 命令を使う目的として正しいものはどれか。',
   NULL::text,
   '["指定パスをマウントポイントとして扱い、そこへの書き込みがイメージの書き込み層に溜まらないようにする", "そのパスをイメージのビルド時にホストの特定フォルダへあらかじめ直結しておく", "そのパスに書き込まれたファイルを、イメージのビルド完了時に自動的に削除する", "そのパスに書かれたファイルを、レジストリへのpush対象から自動的に除外する"]',
   0,
   '[0]',
   'single',
   '{"asked": "VOLUME命令が『データをコンテナ層に残さない』ための仕組みだと理解しているか。", "point": "VOLUME命令は、そこへの書き込みをコンテナの薄い書き込み層に溜め込ませないためのマウントポイント宣言。", "kid": "データベースのデータなど「頻繁に書き換わる場所」をあらかじめ指定しておく命令。指定した場所は、匿名ボリュームという別の入れ物に逃がされ、コンテナ本体の書き込み層を膨らませない。", "eg": "工事現場でゴミがどんどん出る作業場所だけ、あらかじめ別の大きなコンテナ（ゴミ箱）を横に置いておくイメージ。本体の作業スペースにゴミが溜まらない。", "terms": [["VOLUME", "Dockerfileでマウントポイントを宣言する命令。コンテナ起動時に匿名ボリュームが自動作成される。"], ["匿名ボリューム", "名前を指定せず作成されるボリューム。VOLUME命令や-vの匿名指定で作られる。"]], "think": "なぜコンテナ層に溜めたくないのかがカギ。コンテナの書き込み層（CoWの最上位）は、コンテナを消せば消える一時的な場所。データベースのデータのように残したい書き込みをそこに置くと、コンテナを削除した瞬間に消えてしまう。VOLUME命令であらかじめ「ここは別のボリュームに逃がす場所」と宣言しておくことで、書き込みがコンテナのライフサイクルから切り離され、パフォーマンスの面でもオーバーレイ層のCoWコストを避けられる。", "vs": "ホストの特定フォルダへの直結（バインドマウント）はdocker run側の-vや--mountで行う操作で、VOLUME命令自体がホストパスを指定するわけではない。ビルド完了時の自動削除やpush除外の機能はない。", "usecase": "データベースの公式イメージなどで、データディレクトリをVOLUMEに指定し、コンテナを作り直してもデータが失われにくい設計にするのに使う。", "opt": ["正解。書き込みをコンテナ層に溜めず、別のボリュームに逃がすためのマウントポイント宣言。", "ホストの特定フォルダへの直結はdocker run側のバインドマウント操作で行うもので、VOLUME命令自体の機能ではない。", "ビルド完了時の自動削除の機能はない。", "pushの対象から除外する機能ではない。"]}'),

  ('dca-q93', 'Image Creation, Management, and Registry',
   '既存イメージに新しいタグを追加する docker tag myimage:1.0 myimage:latest を実行した場合の説明として正しいものはどれか。',
   NULL::text,
   '["イメージの中身は複製されず、同じイメージIDに新しい呼び名（タグ）が増えるだけ", "イメージ全体が丸ごと複製され、ディスク使用量が2倍になる", "元のタグ（1.0）は自動的に削除され、latestに置き換わる", "レジストリへpushしないと、このコマンド自体が失敗する"]',
   0,
   '[0]',
   'single',
   '{"asked": "docker tagが実体のコピーではなく、同じ実体への『呼び名の追加』だと理解しているか。", "point": "docker tagはイメージを複製しない。同じ実体に別の呼び名（タグ）を増やすだけ。", "kid": "同じ人に「あだ名」を増やすようなもの。呼び方は増えるが、本人（イメージの実体）は1人のまま。ディスクを余分に食わない。", "eg": "1冊の本に「参考書」というラベルと「教科書」というラベルの両方を貼るようなもの。本自体は1冊のまま。", "terms": [["docker tag", "既存イメージ（イメージID）に、新しい参照名（タグ）を追加するコマンド。実体はコピーしない。"], ["イメージID", "イメージの中身から決まる一意の識別子。タグはこのIDを指す別名にすぎない。"]], "think": "なぜ複製にならないのかがカギ。タグはイメージIDという実体を指すただの『名札』であって、実体そのものではない。docker tagは名札を新しく作って同じ実体に貼るだけの操作なので、ファイルの中身（レイヤー）は一切コピーされず、ディスク使用量もほぼ増えない。", "vs": "ディスク使用量が2倍になることはない（実体は共有される）。元のタグ(1.0)は自動削除されない（同じイメージを指す複数のタグが共存できる）。ローカルでの操作なので、レジストリへのpushは不要でコマンド自体は成功する。", "usecase": "同じビルド成果物に、バージョン番号のタグとlatestタグの両方を付けたいときに使う。ビルドをやり直す必要がない。", "opt": ["正解。同じ実体に呼び名（タグ）を追加するだけで、複製は発生しない。", "実体は共有されるため、ディスク使用量はほぼ増えない。", "元のタグは自動削除されず、複数のタグが同じ実体を指したまま共存できる。", "ローカルの操作なのでpushは不要。コマンド自体はローカルだけで完結する。"]}'),

  ('dca-q94', 'Image Creation, Management, and Registry',
   'docker history myimage コマンドで確認できる情報として正しいものはどれか。',
   NULL::text,
   '["各レイヤーを作った命令とそのレイヤーのサイズ", "コンテナの起動中のCPU・メモリ使用量", "そのイメージを使って現在動いているコンテナの一覧", "レジストリ上でそのイメージが何回pullされたかの回数"]',
   0,
   '[0]',
   'single',
   '{"asked": "docker historyがイメージのビルド履歴（命令とサイズ）を見るコマンドだと知っているか。", "point": "各レイヤーがどの命令で作られ、それぞれ何バイトかを見るなら docker history。", "kid": "そのイメージが「どんな命令を積み重ねて作られたか」を、レイヤーごとに古い順（または新しい順）に見せてくれるコマンド。どの命令が容量を食っているかも分かる。", "eg": "ケーキの断面図を見て、どの層（スポンジ・クリーム・フルーツ）がどれだけの厚みかを確認するようなもの。", "terms": [["docker history", "イメージの各レイヤーを作った命令とサイズを一覧表示するコマンド。"]], "think": "レイヤーはDockerfileの命令1つ1つに対応して積み重なる。docker historyはこの積み重ねの記録を逆順にたどり、『この命令でこれだけ容量が増えた』を可視化する。イメージが想定より大きいときに、どの命令（RUN apt installなど）が原因かを特定するのに使う。", "vs": "実行中のリソース使用量は docker stats、動いているコンテナ一覧は docker ps、pull回数のようなレジストリ側の統計情報は docker history では取得できない（レジストリのAPIや管理画面の領域）。", "usecase": "イメージが肥大化してしまったとき、docker historyでどの命令が原因かを特定し、レイヤーを減らす・順番を見直すなどの最適化に使う。", "opt": ["正解。各レイヤーを作った命令とサイズの一覧が見える。", "実行中のリソース使用量はdocker statsの領域で、historyでは見えない。", "現在動いているコンテナ一覧はdocker psの領域で、historyでは見えない。", "pull回数のようなレジストリ側の統計はdocker historyの範囲外。"]}'),

  ('dca-q95', 'Image Creation, Management, and Registry',
   'カレントディレクトリの Dockerfile.prod という名前のファイルを使ってビルドするコマンドはどれか。',
   NULL::text,
   '["docker build -f Dockerfile.prod .", "docker build --file=default .", "docker build --name Dockerfile.prod .", "docker build . Dockerfile.prod"]',
   0,
   '[0]',
   'single',
   '{"asked": "-f（--file）オプションで既定以外の名前のDockerfileを指定できることを知っているか。", "point": "既定名(Dockerfile)以外のファイルを使うなら -f <ファイル名>。", "kid": "普段docker buildは「Dockerfile」という決まった名前のファイルを探すが、-fオプションを付ければ別名のファイルを指定できる。", "eg": "普段は「レシピ」という名前の紙を見て料理するが、「レシピ_本番用」という別の紙を指定して、そちらを見て作ってもらうようなもの。", "terms": [["-f, --file", "docker buildで使うDockerfileのパスを明示的に指定するオプション。既定は ./Dockerfile。"]], "think": "-fオプションはビルドの入力として読む『設計図ファイル』を差し替えるためのもの。本番用と開発用でDockerfileの内容を分けたいときに、ファイル名を変えて -f で使い分けられる。最後の . はビルドコンテキスト（送るファイルの範囲）を表し、-fの対象ファイル名とは別の引数。", "vs": "--file=defaultという書き方はファイル名指定にならない（defaultという名前のファイルを探しに行ってしまう）。--nameというオプションはdocker buildに存在しない。引数の順序を入れ替えただけの docker build . Dockerfile.prod は、Dockerfile.prodをビルドコンテキストの一部として誤解釈させてしまい、-fの指定にはならない。", "usecase": "同じディレクトリに開発用・本番用・テスト用など複数のDockerfile派生を置き、CI/CDで用途ごとに切り替えてビルドしたいときに使う。", "opt": ["正解。-f でファイル名を明示指定する。", "--file=defaultは『default』という名前のファイルを探す指定になり、意図と異なる。", "--nameというオプションはdocker buildに存在しない。", "引数の順序が誤り。-fを使わずファイル名だけ置いても指定にならない。"]}'),

  ('dca-q96', 'Image Creation, Management, and Registry',
   'docker buildx でマルチプラットフォームビルドした結果、レジストリに1つのタグでpushされたイメージを pull すると何が起きるか。',
   NULL::text,
   '["クライアントのCPUアーキテクチャに合った実体が、マニフェストリストを介して自動的に選ばれる", "常にamd64版が優先的にpullされ、arm64版は無視される", "全アーキテクチャ分のイメージがまとめて1つのファイルとしてダウンロードされる", "pullのたびにどのアーキテクチャを使うか手動で選択を求められる"]',
   0,
   '[0]',
   'single',
   '{"asked": "マニフェストリストが1つのタグの裏でアーキテクチャ別実体を自動的に振り分ける仕組みだと理解しているか。", "point": "1つのタグの裏に複数アーキテクチャの実体があり、pull時にクライアントに合うものが自動選択される。", "kid": "「myimage:latest」という1つの名札の裏に、Intel用・ARM用など複数の中身が隠れている。pullする側のマシンに合わせて、Docker側が自動でどの中身を渡すか選んでくれる。", "eg": "同じ商品名の家電でも、コンセントの形が国によって違うので、国内向けにはその国のプラグの製品が自動で届くようなもの。", "terms": [["マニフェストリスト（manifest list）", "1つのタグに対して、複数のCPUアーキテクチャ向け実体（マニフェスト）を束ねる目録。"], ["プラットフォーム自動選択", "pull時にクライアントのOS/アーキテクチャに一致する実体を、マニフェストリストから自動で選ぶ挙動。"]], "think": "なぜタグを1つにまとめられるのかがカギ。もしアーキテクチャごとに別タグ（myimage:amd64、myimage:arm64）にすると、利用者が自分のマシンに合うタグを毎回意識して選ばないといけない。マニフェストリストという目録を1つのタグの裏に置くことで、pull側は自分のCPUを気にせず同じタグ名を打つだけで済み、Docker側が目録を見て一致する実体だけをダウンロードする。", "vs": "amd64が常に優先されるわけではなく、pull元マシンのアーキテクチャに一致するものが選ばれる。全アーキテクチャ分をまとめてダウンロードすることはない（使う分だけ）。手動選択を求められることもない（自動選択が既定の挙動）。", "usecase": "IntelマシンとARMサーバーの両方に同じデプロイ手順（同じイメージタグ）を使い回したいときに使う。", "opt": ["正解。マニフェストリストを介して、pull側のアーキテクチャに合う実体が自動選択される。", "amd64が常に優先されるわけではなく、pull側のアーキテクチャに応じて選ばれる。", "全アーキテクチャ分がまとめてダウンロードされることはない。", "手動選択は不要。自動選択が既定の挙動。"], "viz": "<svg viewBox=\"0 0 340 165\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">1つのタグの裏に複数アーキテクチャの実体</text><rect x=\"105\" y=\"28\" width=\"130\" height=\"24\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"44\" font-size=\"9\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">myimage:latest</text><line x1=\"170\" y1=\"52\" x2=\"170\" y2=\"64\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"60\" y=\"66\" width=\"220\" height=\"20\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"80\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">マニフェストリスト（目録）</text><line x1=\"170\" y1=\"86\" x2=\"60\" y2=\"98\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"20\" y=\"98\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"60\" y=\"111\" font-size=\"7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">linux/amd64</text><line x1=\"170\" y1=\"86\" x2=\"170\" y2=\"98\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"130\" y=\"98\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170\" y=\"111\" font-size=\"7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">linux/arm64</text><line x1=\"170\" y1=\"86\" x2=\"280\" y2=\"98\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><rect x=\"240\" y=\"98\" width=\"80\" height=\"20\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"280\" y=\"111\" font-size=\"7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">windows/amd64</text><text x=\"170\" y=\"138\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">pullする側のCPU/OSに合う実体だけが自動選択される</text><text x=\"170\" y=\"151\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">利用者はタグ名を打つだけでよい</text></svg>"}'),

  ('dca-q97', 'Image Creation, Management, and Registry',
   'docker login を実行したとき、認証情報（パスワード等）の扱いとして正しいものはどれか。',
   NULL::text,
   '["OSのキーチェーンなどcredential helperがあればそこに保存され、無い場合は~/.docker/config.jsonに平文相当で残る", "常にOSのキーチェーン等の安全な場所にのみ保存され、~/.docker/config.jsonのような設定ファイルには一切情報が残らない", "認証情報はどこにも保存されない仕組みになっており、docker系コマンドを打つたびに毎回パスワードの入力が必要になる", "認証情報は環境やcredential helperの有無に関わらず、常に自動的に暗号化されたファイルとして~/.docker/以下に保存される"]',
   0,
   '[0]',
   'single',
   '{"asked": "credential helperの有無で認証情報の保存先・安全性が変わることを理解しているか。", "point": "credential helperがあればOS側の安全な場所に、無ければ設定ファイルに平文相当で残る。", "kid": "docker loginしたときのパスワードは、OSの金庫（キーチェーン等）に預けられればそこに安全に保管される。でもその金庫の設定（credential helper）が入っていないマシンでは、代わりに普通の設定ファイルにそのまま残ってしまう。", "eg": "貴重品をホテルの金庫に預けられればそこが一番安全だが、金庫が無い部屋では引き出しにそのまま置くしかない、というようなもの。", "terms": [["credential helper", "OSのキーチェーンやパスワードマネージャーと連携して認証情報を安全に保管する仕組み（docker-credential-desktopなど）。"], ["~/.docker/config.json", "docker loginの認証情報が記録される設定ファイル。credential helper未設定だと平文相当で残る。"]], "think": "なぜ環境によって安全性が変わるのかがカギ。Docker CLI自体はパスワードをどこかに保存しないと毎回ログインし直す必要があり不便になる。credential helperという仕組みがあれば、OSの安全な保管庫（macOSのキーチェーン等）に橋渡ししてくれるが、これは追加でインストール・設定するものであり、無い環境ではDocker CLIが持つ唯一の保存先である設定ファイルにそのまま書かれてしまう。", "vs": "『常にキーチェーンだけ』ではなく、credential helper未設定の環境ではファイルに残る。『毎回入力が必須』でもない（設定ファイルやhelperに保存されるため2回目以降は省略できる）。『自動的に暗号化される』も誤り。何もしなければ平文相当のまま。", "usecase": "CI環境や共有マシンでdocker loginを使う場合、credential helperを設定するか、認証情報が平文で残るリスクを踏まえた運用にする必要がある。", "opt": ["正解。credential helperの有無で保存先と安全性が変わる。", "credential helperが無い環境では設定ファイルに残るため、常にキーチェーンだけとは限らない。", "設定ファイルやhelperに保存されるため、毎回の入力は必須ではない。", "credential helper無しでは自動暗号化されず、平文相当のまま残る。"]}'),

  ('dca-q98', 'Image Creation, Management, and Registry',
   'docker build --build-arg VERSION=1.2.3 . を実行したとき、VERSIONという値を実際にDockerfile内で使うために必要な準備はどれか。',
   NULL::text,
   '["Dockerfile内で ARG VERSION を事前に宣言しておく", "特に準備は不要で、宣言なしでも自動的に使える", "Dockerfile内で ENV VERSION=default を書いておけば足りる", "docker build時に--build-argを使わずCOPYで渡す必要がある"]',
   0,
   '[0]',
   'single',
   '{"asked": "--build-argで渡した値を使うには、Dockerfile側でARG宣言による受け皿が要ると理解しているか。", "point": "--build-argの値を使うには、Dockerfile側に ARG <名前> の受け皿が要る。", "kid": "docker buildコマンドの外から値を渡しても、Dockerfileの中に「この名前の値を受け取ります」というARG宣言が無いと、その値は使われない（無視される）。", "eg": "手紙を送っても、宛先に対応する郵便受け（ARG宣言）が無ければ配達されず、そのまま届かないのと同じ。", "terms": [["--build-arg", "docker buildコマンドの外から、ビルド時にだけ使う値を渡すオプション。"], ["ARG", "Dockerfile内で、--build-argから受け取る変数名を事前に宣言する命令。宣言が無いと外部からの値は反映されない。"]], "think": "なぜ事前宣言が要るのかがカギ。--build-argはビルドコマンドの外側から渡される値だが、Dockerfileはそれを暗黙に受け取る仕組みを持たない。ARG VERSION という宣言を書くことで、その名前の値を外部から受け取れる『受け皿』が用意され、初めてDockerfile内で$VERSIONのように参照できるようになる。", "vs": "宣言なしで自動的に使えることはない（無視される）。ENVはコンテナ実行時にも残る環境変数の宣言であり、ARGとは別物（--build-argの受け皿にはならない）。COPYで渡す方法とは無関係。", "usecase": "ビルド時だけ知りたいバージョン番号やGitのコミットハッシュなどを、Dockerfileを書き換えずにCIから注入したいときに使う。", "opt": ["正解。ARG宣言という受け皿が無いと外部からの値は反映されない。", "宣言なしでは値は反映されず無視される。", "ENV宣言はARGの代わりにはならない。役割が異なる。", "COPYは無関係。値を渡すのは--build-argとARGの組み合わせ。"]}'),

  ('dca-q99', 'Installation and Configuration',
   '複数ノードで docker swarm init --advertise-addr 192.168.1.10 のように --advertise-addr を指定する主な理由はどれか。',
   NULL::text,
   '["ノードに複数のネットワークインターフェースがある場合、他ノードに通知する接続先アドレスを明示するため", "参加時のパスワードの代わりに、このIPアドレスを使って認証を行うため", "デーモンが出力するログを、このアドレス宛のサーバーへ転送するため", "各コンテナに割り当てられるIPアドレスの範囲を、この値の範囲に固定するため"]',
   0,
   '[0]',
   'single',
   '{"asked": "advertise-addrが『どのIPで他ノードに見つけてもらうか』の指定であると理解しているか。", "point": "複数NICがあるマシンで、他ノードに知らせる接続先アドレスを明示するのが --advertise-addr。", "kid": "1台のマシンにネットワークの入口（インターフェース）が複数あるとき、「他のノードはこのIPアドレス宛に私に話しかけてね」と教えてあげる設定。", "eg": "1人の人が複数の電話番号を持っているとき、「連絡はこの番号にかけてください」と1つを指定して周知するようなもの。", "terms": [["--advertise-addr", "他のノードに通知する、このマネージャー/ワーカーへの接続先IPアドレス（またはインターフェース名）。"], ["NIC (Network Interface Card)", "マシンが持つネットワークの接続口。1台に複数存在することがある。"]], "think": "なぜ明示が必要なのかがカギ。クラウドやマルチホームのマシンでは、プライベートIP・パブリックIP・VPN用IPなど複数のアドレスを1台が持つことがある。Dockerが自動で1つを選んでしまうと、他ノードから届かないアドレスを選んでしまう可能性がある。--advertise-addrで明示することで、確実に他ノードから到達できるアドレスを指定できる。", "vs": "認証はjoin-tokenが担う役割で、advertise-addr自体は認証情報ではない。ログ転送やコンテナのIP範囲設定とも無関係（IP範囲はdefault-address-poolsなど別の設定）。", "usecase": "複数のネットワークに接続されたクラウドインスタンスでSwarmを構成するとき、意図しないインターフェースが選ばれるのを防ぐために明示する。", "opt": ["正解。他ノードに通知する接続先アドレスを明示する設定。", "認証はjoin-tokenの役割で、advertise-addr自体は認証情報ではない。", "ログ転送の設定ではない。", "コンテナのIPアドレス範囲の設定ではない（それは別の設定項目）。"]}'),

  ('dca-q100', 'Installation and Configuration',
   'dockerd をTCPソケットで公開しつつ --tlsverify を設定しない場合の主なリスクはどれか。',
   NULL::text,
   '["ネットワーク上の誰でもDockerデーモンを操作でき、事実上ホストのroot権限を握られる", "パフォーマンスが著しく低下するだけで、セキュリティ上の問題は無い", "コンテナ同士の通信が暗号化されなくなるだけ", "イメージのpullが一切できなくなる"]',
   0,
   '[0]',
   'single',
   '{"asked": "認証なしでdockerdを公開することが『ホストの制御を渡す』のと同義であると理解しているか。", "point": "認証なしでdockerdをTCP公開するのは、ホストの制御権を誰にでも渡すのとほぼ同じ危険がある。", "kid": "Dockerの司令塔（デーモン）を、鍵をかけずにネットワークへ開けっ放しにする状態。デーモンを操作できる人は、コンテナ経由でホストのファイルにも自由にアクセスできてしまう。", "eg": "会社の入退室管理システムを、暗証番号なしで誰でも入れる状態にしてしまうようなもの。中の書類（ホストの中身）まで自由にアクセスされる。", "terms": [["dockerd", "Dockerの本体（デーモン）。CLIからの指示を受けて実際にコンテナを操作する。"], ["--tlsverify", "デーモンとクライアント双方の証明書を検証し、正規のクライアントだけが接続できるようにする設定。"]], "think": "なぜホストの制御を握られるのかがカギ。Dockerデーモンを操作できる人は、任意のイメージから、ホストのファイルシステムを丸ごとマウントしたコンテナを起動できる（例: -v /:/hostのようなマウント）。つまりデーモンへのアクセス権は、事実上ホストのrootアクセス権と同等の力を持つ。認証（--tlsverify等）を設定せずにTCPで公開すると、ネットワークに到達できる誰もがこの力を手にしてしまう。", "vs": "パフォーマンス低下が主な問題ではない（本質はアクセス制御の欠如）。コンテナ間通信の暗号化とは別の話（それはSwarmのノード間通信などの領域）。pullができなくなるという話でもない（むしろ無制限に操作できてしまう）。", "usecase": "リモートからdockerdを操作する必要がある場合は、TCP公開自体を避けるかSSH経由にするか、どうしても公開するなら必ずTLS相互認証を設定する。", "opt": ["正解。認証なしでの公開はホストの制御権を渡すのとほぼ同義。", "本質的な問題はセキュリティであり、パフォーマンスの問題ではない。", "コンテナ間通信の暗号化とは別の話。", "pullができなくなるという話ではなく、むしろ何でもできてしまう危険がある。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">認証なしでdockerdを公開＝ホストの制御権を渡す</text><rect x=\"20\" y=\"32\" width=\"90\" height=\"28\" rx=\"4\" fill=\"#241a1a\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"65\" y=\"50\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">誰でも接続可</text><line x1=\"110\" y1=\"46\" x2=\"148\" y2=\"46\" stroke=\"#c47070\" stroke-width=\"1.5\"/><rect x=\"150\" y=\"32\" width=\"90\" height=\"28\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"195\" y=\"50\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">dockerd</text><line x1=\"240\" y1=\"46\" x2=\"278\" y2=\"46\" stroke=\"#c47070\" stroke-width=\"1.5\"/><rect x=\"240\" y=\"32\" width=\"90\" height=\"28\" rx=\"4\" fill=\"#241a1a\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"285\" y=\"50\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">ホスト全体</text><text x=\"170\" y=\"82\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">デーモンを操作できる＝任意のコンテナから</text><text x=\"170\" y=\"95\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ホストのファイル全体をマウントして読み書きできる</text><text x=\"170\" y=\"120\" font-size=\"8\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">--tlsverify で正規のクライアントだけに絞る</text></svg>"}'),

  ('dca-q101', 'Installation and Configuration',
   'DOCKER_HOST 環境変数の役割として正しいものはどれか。',
   NULL::text,
   '["docker CLIがどのDockerデーモン（ソケットやリモートホスト）に接続するかを指定する", "コンテナの中で動くアプリが参照するホスト名を指定する", "docker buildが使うビルドキャッシュの保存場所を指定する", "Docker Hubのミラーサーバーを指定する"]',
   0,
   '[0]',
   'single',
   '{"asked": "DOCKER_HOSTがCLIの接続先デーモンを切り替える環境変数だと理解しているか。", "point": "docker CLIがどのデーモンに話しかけるかを決めるのが DOCKER_HOST。", "kid": "docker コマンドを打ったとき、「どこにいるDockerの本体（デーモン）に指示を送るか」の宛先を指定する環境変数。既定はローカルのソケットだが、リモートのDockerに向けることもできる。", "eg": "電話をかけるとき、既定の相手（ローカル）ではなく、あらかじめ別の宛先番号（リモートホスト）を設定しておくようなもの。", "terms": [["DOCKER_HOST", "docker CLIの接続先デーモンを指定する環境変数。既定は unix:///var/run/docker.sock。tcp://host:2375 のようにリモートも指定できる。"], ["docker context", "DOCKER_HOSTを含む接続設定を、名前を付けて切り替えられるようにした仕組み。"]], "think": "docker CLIとdockerdは別プロセスであり、CLIはあくまで『どこかにいるデーモンに指示を送るだけの窓口』。DOCKER_HOSTはその窓口が指示を送る宛先を決める設定で、これを変えるだけで、同じCLIコマンドがローカルにもリモートにも向けられる。docker contextはこの設定を名前付きで管理し、切り替えやすくした仕組み。", "vs": "コンテナ内アプリのホスト名解決とは無関係（それはコンテナのネットワーク設定の話）。ビルドキャッシュの保存場所やDocker Hubのミラー設定とも別の項目。", "usecase": "手元のCLIから、離れたサーバー上のDockerデーモンを操作したいときに DOCKER_HOST（またはdocker context）を切り替えて使う。", "opt": ["正解。CLIがどのデーモンに接続するかを決める環境変数。", "コンテナ内アプリのホスト名解決とは無関係。", "ビルドキャッシュの保存場所の設定ではない。", "Docker Hubのミラー設定ではない（それはdaemon.jsonの別項目）。"]}'),

  ('dca-q102', 'Installation and Configuration',
   'daemon.json に default-address-pools を設定する主な目的はどれか。',
   NULL::text,
   '["Dockerが自動作成するネットワークのIPアドレス範囲が、社内の他システムと衝突しないようにする", "新しく起動する各コンテナが使えるCPUとメモリの初期割当量をあらかじめ決めておく", "docker pull/pushが既定で使うレジストリの接続アドレスを変更する", "Swarmを初期化するマネージャーノードの初期IPアドレスを固定する"]',
   0,
   '[0]',
   'single',
   '{"asked": "default-address-poolsが『Dockerが自動で割り振るIPレンジ』を管理者側で調整する設定だと理解しているか。", "point": "自動作成されるDockerネットワークのIP範囲が社内ネットワークと被らないようにするのが default-address-pools。", "kid": "Dockerがネットワークを自動で作るとき、勝手に使うIPアドレスの範囲をあらかじめ指定しておく設定。これを決めておかないと、たまたま社内の別システムと同じ番地を使ってしまい、通信がおかしくなることがある。", "eg": "マンションの部屋番号を自動採番するとき、あらかじめ「101号室から使ってください」と範囲を決めておかないと、他の建物とかぶってしまうことがある。", "terms": [["default-address-pools", "daemon.jsonでDockerネットワーク作成時に使うIPアドレスプールの範囲・サブネットサイズを指定する設定。"], ["IPアドレスの衝突", "同じIP範囲が複数のネットワークで使われてしまい、正しく通信できなくなる状態。"]], "think": "なぜ衝突が起きるのかがカギ。Dockerはネットワークを作るたびに、既定のプールから自動的にサブネットを割り当てる。企業のVPNや他システムが既に使っているIP範囲と、この既定プールがたまたま重なると、コンテナからその宛先へ正しく通信できなくなる。default-address-poolsで自社のIP設計にぶつからない範囲を明示しておけば、この衝突を未然に防げる。", "vs": "CPU・メモリの初期割当とは無関係（それはリソース制限の設定）。レジストリの接続先やSwarmマネージャーのIP固定とも別の項目。", "usecase": "複数のDockerホストや社内ネットワークと共存する環境で、コンテナネットワークのIP範囲を計画的に管理したいときに設定する。", "opt": ["正解。自動作成されるネットワークのIP範囲が社内システムと衝突しないよう調整する。", "CPU・メモリの割当量とは無関係。", "レジストリの接続先設定ではない。", "Swarmマネージャーの固定IPを決める設定ではない。"]}'),

  ('dca-q103', 'Installation and Configuration',
   'daemon.json に "live-restore": true を設定する目的はどれか。',
   NULL::text,
   '["dockerdを再起動・アップグレードしても、動いているコンテナをそのまま実行させ続ける", "コンテナが出力するログを、ディスクではなくメモリ上だけに保存する", "dockerdがクラッシュしたときに、自動で無限に再起動させ続ける", "起動する全コンテナのファイルシステムを、常に読み取り専用にする"]',
   0,
   '[0]',
   'single',
   '{"asked": "live-restoreが『デーモンの再起動』とコンテナの実行継続を切り離す設定だと理解しているか。", "point": "dockerdを再起動しても、動作中のコンテナを止めずに継続させるのが live-restore。", "kid": "Dockerの本体（デーモン）をアップグレードしたり再起動したりするとき、今動いているコンテナまで一緒に止めてしまわないようにする設定。", "eg": "エレベーターの制御盤（デーモン）を交換工事している間も、既にエレベーターに乗っている人（コンテナ）は降ろされずそのまま運転が続く、というイメージ。", "terms": [["live-restore", "daemon.jsonの設定。デーモン再起動・アップグレード時にも既存コンテナを実行し続けさせる。"], ["dockerd", "Dockerの司令塔にあたるデーモンプロセス。コンテナのプロセス自体とは別プロセス。"]], "think": "なぜ切り離せるのかがカギ。コンテナのプロセス実体は、実はdockerd本体とは別のプロセス（containerd/runc経由）として動いている。dockerdが一旦止まっても、実行中のコンテナプロセス自体はOS上で生き続けられる。live-restoreを有効にすると、dockerd再起動後にその生きているコンテナを『見失わず』再び管理下に戻す動作になり、結果として利用者からは『無停止でデーモンをアップグレードできた』ように見える。", "vs": "ログの保存先（メモリのみ）を決める設定ではない（それはログドライバーの設定）。クラッシュ時の自動再起動を無限に行う設定でもない（systemdのenableの領域）。ファイルシステムを読み取り専用にする設定とも無関係（--read-onlyの話）。", "usecase": "本番環境でDocker Engine自体をアップグレードする際、稼働中のサービスを止めずに済ませたいときに有効にする。", "opt": ["正解。デーモン再起動時にも既存コンテナを止めずに継続させる。", "ログの保存方式の設定ではない。", "クラッシュ時の自動再起動を無限に行う設定ではない（それはsystemdの役割）。", "ファイルシステムを読み取り専用にする設定ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"8.7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">live-restore：デーモンが止まってもコンテナは続く</text><rect x=\"20\" y=\"32\" width=\"140\" height=\"30\" rx=\"4\" fill=\"#241a1a\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"90\" y=\"46\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">dockerd 再起動中</text><text x=\"90\" y=\"58\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（司令塔が一時不在）</text><rect x=\"180\" y=\"32\" width=\"140\" height=\"30\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"250\" y=\"46\" font-size=\"8\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">コンテナは実行継続</text><text x=\"250\" y=\"58\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（別プロセスとして動く）</text><text x=\"170\" y=\"92\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナの実体はcontainerd/runc経由の別プロセス。</text><text x=\"170\" y=\"105\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">dockerd再起動後、また管理下に戻ってくる</text><text x=\"170\" y=\"128\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">本番アップグレードを無停止で行うための設定</text></svg>"}'),

  ('dca-q104', 'Installation and Configuration',
   'rootless モードでDockerデーモンを動かすことと、userns-remap（ユーザー名前空間の再マッピング）の違いとして正しいものはどれか。',
   NULL::text,
   '["rootlessはデーモン自体をroot権限なしで動かし、userns-remapはコンテナ内rootをホストの非特権UIDへ対応付ける", "両者は全く同じ機能で、呼び方が違うだけ", "rootlessはコンテナ内のUIDを変換し、userns-remapはデーモンをroot無しで動かす（説明が逆）", "どちらもコンテナのネットワーク名前空間だけを分離する機能"]',
   0,
   '[0]',
   'single',
   '{"asked": "『デーモン自体の権限』と『コンテナ内UIDの見え方』という、似て非なる2つの隔離手段を区別できるか。", "point": "rootlessは『デーモンの実行権限』を落とす仕組み、userns-remapは『コンテナ内rootの実体』を非特権ユーザーに対応付ける仕組み。", "kid": "rootlessは、Dockerの本体（デーモン）自体を最初からroot以外のユーザーとして動かす仕組み。userns-remapは、デーモンはrootのままでも、コンテナの中で見えている「root」を、実はホストの一般ユーザーに対応付けてしまう仕組み。守る対象が少し違う。", "eg": "rootlessは『警備員（デーモン）自体を最初から一般社員の権限にする』、userns-remapは『社長室（コンテナ内root）にいる人を、実は名札だけ社長で中身は一般社員にすり替えておく』ようなもの。", "terms": [["rootless mode", "dockerd自体を非rootユーザーとして起動する構成。デーモンが乗っ取られてもホストroot権限には直結しにくい。"], ["userns-remap", "コンテナ内のUID 0（root）を、ホスト上の非特権UID範囲にマッピングする設定。コンテナがコンテナを脱出してもホストroot権限にならない。"]], "think": "なぜ2つとも必要になりうるのかがカギ。userns-remapはコンテナ内から見た『root』の実体をすり替えるだけで、デーモン自体は依然としてホストのrootで動いている。もしデーモン自体が攻撃されればホストへの影響は大きい。rootlessはこのデーモン自体の権限を落とすことで、そもそもの土台部分の被害を抑える。両者は防ぐ対象（コンテナ内root vs デーモン自体）が違うため、片方だけでは守れない範囲がある。", "vs": "同じ機能ではなく、対象が違う。説明が逆になっているわけでもない（rootless＝デーモンの権限、userns-remap＝コンテナ内UIDのマッピング、が正しい対応）。ネットワーク名前空間の分離とはどちらも直接関係ない（それはnetworkの隔離の話）。", "usecase": "デーモン自体を乗っ取られるリスクまで下げたい環境ではrootless modeを、コンテナ内rootの脱出リスクを下げたい環境ではuserns-remapを検討する。両方組み合わせることもある。", "opt": ["正解。rootlessはデーモン自体の権限を落とし、userns-remapはコンテナ内rootを非特権UIDへ対応付ける。", "対象が異なるため、同じ機能ではない。", "説明が逆になっている。rootlessとuserns-remapの役割が入れ替わっている。", "ネットワーク名前空間の分離とは直接関係ない機能。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">守る対象が違う2つの仕組み</text><rect x=\"15\" y=\"30\" width=\"145\" height=\"50\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"87.5\" y=\"44\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">rootless mode</text><text x=\"87.5\" y=\"58\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">デーモン自体を</text><text x=\"87.5\" y=\"69\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">非rootユーザーで動かす</text><rect x=\"180\" y=\"30\" width=\"145\" height=\"50\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"252.5\" y=\"44\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">userns-remap</text><text x=\"252.5\" y=\"58\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ内rootを</text><text x=\"252.5\" y=\"69\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ホストの一般UIDへ対応付け</text><text x=\"170\" y=\"100\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">rootless＝土台（デーモン）自体の権限を落とす</text><text x=\"170\" y=\"113\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">userns-remap＝コンテナ内から見えるrootをすり替える</text><text x=\"170\" y=\"136\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">対象が違うので、組み合わせて使うこともある</text></svg>"}'),

  ('dca-q105', 'Installation and Configuration',
   'Docker Engineの推奨インストール方法として、公式が非推奨としているものはどれか。',
   NULL::text,
   '["インターネット上のスクリプトをそのままパイプでshellに流し込むcurl | sh方式を本番環境で常用すること", "OSの公式パッケージマネージャー（apt/yum等）でDockerの公式リポジトリから入れること", "公式ドキュメントに従ってGPG鍵を検証してからリポジトリを追加すること", "Docker Desktopを使い、内部でLinux VMを介して動かすこと（Mac/Windows）"]',
   0,
   '[0]',
   'single',
   '{"asked": "get.docker.com のようなconvenience scriptが、検証プロセスを飛ばす分だけ本番運用には注意が必要だと理解しているか。", "point": "curl | sh方式の簡易インストールは検証がなく、本番の恒常運用には非推奨。", "kid": "「ネットからダウンロードしたスクリプトをそのまま実行して入れる」やり方は、お試しには便利だが、中身を検証せずに実行することになるので、本番環境で定常的に使う入れ方としては推奨されない。", "eg": "知らない人から渡された封筒を、中身を確認せずにそのまま開けて使うようなもの。試しに1回使うのと、毎回それに頼るのとでは安全性の話が変わる。", "terms": [["convenience script", "get.docker.comなどで配布される、curl | shで実行する簡易インストーラー。検証工程を省略しがちなため注意が要る。"], ["公式パッケージリポジトリ", "GPG鍵の検証を経て、パッケージマネージャー経由でインストールできる正規の配布経路。"]], "think": "なぜ検証の有無が問題なのかがカギ。パッケージマネージャー経由のインストールは、GPG鍵で配布元の正当性を検証してからパッケージを入れる工程が組み込まれている。curl | sh方式は、ダウンロードしたスクリプトの中身を確認せずにそのまま実行することになりやすく、通信経路や配布元が偽装された場合に検知しづらい。開発機での素早い試用には便利だが、本番の恒常運用の入れ方としては公式リポジトリ経由が推奨される。", "vs": "パッケージマネージャー経由のインストールやGPG鍵検証、Docker Desktopの利用は、いずれも公式が案内する正規の入れ方で、非推奨とはされていない。", "usecase": "本番サーバーへのDocker導入では、GPG鍵検証を伴う公式リポジトリからのインストール手順を採用し、curl | sh方式は検証環境や個人PCでの一時利用にとどめる。", "opt": ["正解。検証工程が無いため、本番の恒常運用には非推奨とされる。", "公式パッケージリポジトリ経由のインストールは推奨される正規の方法。", "GPG鍵検証を伴う手順は推奨される正規の方法。", "Docker Desktopの利用自体は、Mac/Windows向けの正規の方法として案内されている。"]}'),

  ('dca-q106', 'Networking',
   'docker network create --subnet 10.20.0.0/16 --gateway 10.20.0.1 mynet の効果として正しいものはどれか。',
   NULL::text,
   '["新しいネットワークが指定したサブネットとゲートウェイで作成される", "既存のdocker0ブリッジのサブネットが上書きされる", "全コンテナが強制的にこのネットワークへ移動させられる", "指定したサブネットは無視され、Dockerの既定プールから自動選択される"]',
   0,
   '[0]',
   'single',
   '{"asked": "--subnet/--gatewayが新規ネットワーク作成時のIP範囲を明示的に指定するオプションだと理解しているか。", "point": "新しいネットワークのIP範囲・ゲートウェイを自分で決めたいなら --subnet と --gateway を指定する。", "kid": "Dockerに新しいネットワークを作ってもらうとき、「このIP範囲を使ってね」「出入り口(ゲートウェイ)はこのアドレスね」と自分で指定するオプション。", "eg": "新しい町を作るとき、区画割り（サブネット）と町の入口の場所（ゲートウェイ）を自分で設計図に書き込むようなもの。", "terms": [["--subnet", "作成するネットワークのIPアドレス範囲をCIDR形式で指定するオプション。"], ["--gateway", "そのサブネット内でゲートウェイとして使うIPアドレスを指定するオプション。"]], "think": "指定しなければDockerは既定のアドレスプールから自動でサブネットを割り当てるが、社内の他システムと衝突する可能性がある。--subnetと--gatewayを明示することで、既存のネットワーク設計に合わせた範囲を自分で決められる。", "vs": "既存のdocker0ブリッジの設定を上書きするわけではない（これは新規ネットワークを作るコマンド）。既存コンテナが強制移動させられることもない（コンテナは明示的に接続し直す必要がある）。指定したサブネットが無視されることもない（明示指定が優先される）。", "usecase": "複数のDockerネットワークやSwarmのoverlayネットワークで、IPレンジが重ならないよう計画的に割り当てたいときに使う。", "opt": ["正解。指定したサブネットとゲートウェイで新しいネットワークが作成される。", "既存のdocker0ブリッジには影響しない。これは新規ネットワーク作成コマンド。", "既存コンテナが強制移動することはない。", "指定は無視されない。明示した値が優先して使われる。"]}'),

  ('dca-q107', 'Networking',
   'docker run --add-host db.internal:10.0.0.5 nginx の効果として正しいものはどれか。',
   NULL::text,
   '["コンテナ内の/etc/hostsに db.internal のエントリが追加され、名前解決できるようになる", "コンテナ側ではなく、Dockerホスト自身の/etc/hostsファイルが書き換えられてしまう", "コンテナが問い合わせに使う外部DNSサーバーの設定自体が、このアドレスに変更される", "コンテナが実際に起動しているDockerホスト自体のIPアドレスが、指定した値に変更される"]',
   0,
   '[0]',
   'single',
   '{"asked": "--add-hostがコンテナ内の/etc/hostsに静的なエントリを追加するオプションだと理解しているか。", "point": "コンテナの中の/etc/hostsに固定の名前解決エントリを足すのが --add-host。", "kid": "コンテナの中にある「名前とIPの対応表（/etc/hosts）」に、自分で1行追加するオプション。DNSサーバーを介さずに、その名前だけは決め打ちのIPで解決される。", "eg": "普段は電話帳（DNS）で番号を調べるが、特定の相手だけは自分のメモ帳（/etc/hosts）に直接番号を書いておいて、そちらを優先して使うようなもの。", "terms": [["--add-host", "docker run時に、コンテナ内の/etc/hostsへ『名前:IP』のエントリを追加するオプション。"], ["/etc/hosts", "名前からIPアドレスへの対応を、DNSに問い合わせず直接解決するためのファイル。"]], "think": "DNSサーバーを新設・変更できない環境でも、特定のホスト名だけをコンテナ内で決め打ちのIPに解決させたいことがある。--add-hostは、コンテナ起動時にそのエントリを/etc/hostsへ直接書き込むことで、DNS設定を変えずにピンポイントで名前解決を差し替えられる。", "vs": "ホスト側の/etc/hostsは書き換えない（あくまでコンテナ内部の話）。外部DNSサーバーの設定変更でもない。コンテナが起動するホスト自体を変更する機能でもない。", "usecase": "テスト環境で、まだDNSに登録されていない社内サービスの名前をコンテナ内から解決させたいときに使う。", "opt": ["正解。コンテナ内の/etc/hostsにエントリが追加される。", "ホスト側の/etc/hostsには影響しない。", "外部DNSサーバーの設定は変更されない。", "コンテナが起動するホスト自体を変更する機能ではない。"]}'),

  ('dca-q108', 'Networking',
   '同じカスタムブリッジネットワーク上のコンテナに docker run --network-alias api --network mynet myimage で追加のエイリアス（別名）を与えた場合の効果はどれか。',
   NULL::text,
   '["同じネットワーク内の他コンテナから、コンテナ名に加えて「api」という名前でも名前解決できるようになる", "コンテナのホスト名自体がapiという名前に書き換わってしまい、元のコンテナ名は使えなくなる", "そのコンテナが、指定したネットワークとは別のネットワークへ自動的に複製される", "Dockerホストマシン自身から、apiという名前で直接そのコンテナへアクセスできるようになる"]',
   0,
   '[0]',
   'single',
   '{"asked": "--network-aliasがコンテナ名に加えて別名を『追加』するオプションであり、置き換えではないと理解しているか。", "point": "--network-aliasは名前を置き換えず、既存のコンテナ名に加えて別名を追加する。", "kid": "同じネットワークの中で、そのコンテナを呼べる名前を追加する機能。もともとのコンテナ名でも呼べるし、追加した別名（api等）でも呼べるようになる。", "eg": "1人の人が「本名」に加えて「あだ名」でも呼びかけに応えられるようにするようなもの。本名が使えなくなるわけではない。", "terms": [["--network-alias", "そのネットワーク内で、コンテナ名とは別に追加のDNS名を持たせるオプション。"], ["組み込みDNS", "カスタムブリッジ/overlayネットワークで、コンテナ名やエイリアスをIPへ解決してくれるDocker内蔵の仕組み。"]], "think": "組み込みDNSは、コンテナ名だけでなく--network-aliasで追加した名前も同じように解決してくれる。これにより、同じサービスを複数の名前（例えばレガシー名と新名称）で呼べるようにしたり、複数コンテナに同じエイリアスを付けて簡易的な名前ベースの分散を作ったりできる。", "vs": "コンテナ本来の名前が使えなくなるわけではない（追加であって置き換えではない）。別ネットワークへの複製は起きない。この名前解決はネットワーク内部の組み込みDNSの話であり、ホストマシン側からそのままapiという名前で引けるわけではない。", "usecase": "同じネットワーク内の複数コンテナに共通のエイリアスを付け、クライアント側からは1つの名前だけを意識させたいときに使う。", "opt": ["正解。既存のコンテナ名に加えて、追加の名前でも名前解決できるようになる。", "元のコンテナ名が使えなくなるわけではない。追加であって置き換えではない。", "別ネットワークへの複製は起きない。", "ホストマシン側からこの名前で直接引けるわけではない。ネットワーク内部の話。"]}'),

  ('dca-q109', 'Networking',
   'Swarmのoverlayネットワークを --attachable オプション付きで作成する目的として正しいものはどれか。',
   NULL::text,
   '["Swarmサービスのタスクだけでなく、docker run で起動した単独のコンテナもそのoverlayネットワークに参加できるようにする", "作成したoverlayネットワークを、このSwarmクラスターの外にある別のSwarmクラスターからも操作できるようにする", "作成するoverlayネットワーク上を流れる全通信の暗号化を無効化し、スループットの速度を優先させる", "本来はSwarmマネージャーの承認が必要なネットワーク作成の手続きを省略して、誰でも作成できるようにする"]',
   0,
   '[0]',
   'single',
   '{"asked": "attachableが『Swarmサービス専用だったoverlayネットワークに、単独コンテナも参加できるようにする』オプションだと理解しているか。", "point": "attachableを付けると、Swarmサービスでない単独コンテナもそのoverlayネットワークに参加できる。", "kid": "普段overlayネットワークはSwarmのサービス同士をつなぐためのものだが、attachableを付けておくと、docker run で普通に起動しただけの単発コンテナも仲間に入れるようになる。", "eg": "普段は社員専用の会議室（overlay）だが、「ゲスト入室可」の札（attachable）を付けておくと、外部の人（単独コンテナ）も一時的に入れるようになる、というイメージ。", "terms": [["--attachable", "overlayネットワーク作成時に付けるオプション。Swarmサービス以外の単独コンテナも接続を許可する。"], ["overlayネットワーク", "複数ホストにまたがるコンテナ同士をつなぐSwarm向けの仮想ネットワーク（VXLANで実現）。"]], "think": "既定のoverlayネットワークは、Swarmのスケジューラが配置するサービスタスクのために作られており、docker run で起動しただけの単独コンテナはそのままでは参加できない。attachableを付けることで、デバッグ用の一時的なコンテナや、Swarm管理外のツールを、同じoverlayネットワークに一時的に接続してサービスと通信させることができる。", "vs": "別クラスターからの操作を許可する機能ではない。暗号化の無効化とは無関係（暗号化は別のオプション --opt encrypted）。マネージャーの承認プロセス自体を変える機能でもない。", "usecase": "Swarmサービスと同じoverlayネットワークに一時的なデバッグ用コンテナをつなぎ、内部の通信状況を調査したいときに使う。", "opt": ["正解。Swarmサービス以外の単独コンテナもそのoverlayネットワークに参加できるようになる。", "別クラスターからの操作を許可する機能ではない。", "暗号化の有無とは無関係。それは別のオプションで制御する。", "マネージャーの承認プロセスを変える機能ではない。"], "viz": "<svg viewBox=\"0 0 340 168\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"8.7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">attachable：単独コンテナもoverlayに参加できる</text><rect x=\"20\" y=\"30\" width=\"300\" height=\"70\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"44\" font-size=\"8\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">overlayネットワーク（attachable）</text><rect x=\"35\" y=\"54\" width=\"90\" height=\"26\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"80\" y=\"68\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Swarmタスク</text><text x=\"80\" y=\"78\" font-size=\"6.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(サービス経由)</text><rect x=\"135\" y=\"54\" width=\"90\" height=\"26\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"180\" y=\"68\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Swarmタスク</text><rect x=\"235\" y=\"54\" width=\"70\" height=\"26\" rx=\"4\" fill=\"#2a2416\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"270\" y=\"68\" font-size=\"7.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">docker run</text><text x=\"270\" y=\"78\" font-size=\"6.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">単独コンテナ</text><text x=\"170\" y=\"118\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">既定のoverlayはSwarmサービス専用。</text><text x=\"170\" y=\"131\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">attachableを付けると単独コンテナも同じ網に混ぜられる</text><text x=\"170\" y=\"152\" font-size=\"7.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">デバッグ用コンテナをサービスと同じ網につなぐのに便利</text></svg>"}'),

  ('dca-q110', 'Networking',
   '2つの異なるカスタムブリッジネットワーク（netA、netB）にそれぞれ接続されたコンテナ同士は、既定でどうなるか。',
   NULL::text,
   '["互いに直接通信できない。同じネットワークに接続しない限り分離される", "同じホスト上なら常に自動的に通信できる", "片方のネットワークがもう片方を自動的に内包する", "ホストのファイアウォール設定次第で常に変わり、Docker側の既定動作は無い"]',
   0,
   '[0]',
   'single',
   '{"asked": "異なるDockerネットワーク間はデフォルトで分離（isolation）されていると理解しているか。", "point": "別々のDockerネットワークに接続されたコンテナ同士は、既定では直接通信できない。", "kid": "違う「島」（ネットワーク）にいるコンテナ同士は、同じ島（同じネットワーク）に一緒に乗らない限り、直接は行き来できない。", "eg": "同じマンションの中でも、別々の会社が借りているフロアの間には、通行できる内部ドアが無いようなもの。", "terms": [["ネットワーク分離（isolation）", "異なるDockerネットワークに接続されたコンテナ同士が、既定では直接通信できない性質。"], ["ブリッジネットワーク", "同一ホスト内でコンテナ同士をつなぐ仮想ネットワーク。作成したネットワークごとに分離される。"]], "think": "なぜ分離されるのかがカギ。Dockerネットワークはそれぞれ独立した仮想ネットワークセグメントとして扱われる。これは意図的な設計で、例えばフロントエンド用のネットワークとデータベース用のネットワークを分けておけば、フロントの脆弱性を突かれても、直接データベースのネットワークへは踏み込めない。通信させたい場合は、両方のネットワークにコンテナを接続するか、片方のコンテナをもう一方のネットワークにも参加させる必要がある。", "vs": "同じホスト上でも自動的には通信できない（ネットワークが違えば分離される）。片方がもう片方を内包することもない。この分離はDocker自体の既定動作であり、ホストのファイアウォール設定に依存する話ではない。", "usecase": "フロントエンド・バックエンド・データベースをそれぞれ別のネットワークに分け、必要な通信経路だけを意図的につなぐことで、被害範囲を限定するネットワーク設計に使う。", "opt": ["正解。既定では別ネットワーク間のコンテナは直接通信できない。", "同じホスト上でも、ネットワークが違えば自動的には通信できない。", "片方がもう片方を内包することはない。", "この分離はDocker自体の既定動作で、ホストのファイアウォール設定に依存する話ではない。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">違うネットワークは、既定では行き来できない</text><rect x=\"20\" y=\"32\" width=\"130\" height=\"60\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"85\" y=\"46\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">netA</text><rect x=\"35\" y=\"56\" width=\"45\" height=\"22\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"57.5\" y=\"70\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">web</text><rect x=\"90\" y=\"56\" width=\"45\" height=\"22\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"112.5\" y=\"70\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">app</text><rect x=\"190\" y=\"32\" width=\"130\" height=\"60\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255\" y=\"46\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">netB</text><rect x=\"205\" y=\"56\" width=\"45\" height=\"22\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"227.5\" y=\"70\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">db</text><rect x=\"260\" y=\"56\" width=\"45\" height=\"22\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"282.5\" y=\"70\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cache</text><line x1=\"150\" y1=\"62\" x2=\"190\" y2=\"62\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/><text x=\"170\" y=\"56\" font-size=\"7\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">遮断</text><text x=\"170\" y=\"116\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">フロント用とDB用を別ネットワークに分けると、</text><text x=\"170\" y=\"129\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">フロントが破られてもDBへ直接は踏み込めない</text></svg>"}'),

  ('dca-q111', 'Networking',
   'docker run --dns 8.8.8.8 myimage の効果として正しいものはどれか。',
   NULL::text,
   '["そのコンテナが名前解決に使うDNSサーバーを個別に指定する", "ホスト全体のDNS設定がこのアドレスに置き換わる", "コンテナ間のコンテナ名解決（組み込みDNS）が無効になる", "イメージのpull元レジストリがこのアドレスに変更される"]',
   0,
   '[0]',
   'single',
   '{"asked": "--dnsがそのコンテナ単位の名前解決先を指定するオプションだと理解しているか。", "point": "そのコンテナだけが使うDNSサーバーを個別に指定するのが --dns。", "kid": "そのコンテナが「わからない名前を聞きに行く先（DNSサーバー）」を、個別に指定するオプション。他のコンテナやホスト全体には影響しない。", "eg": "1人だけ、いつもと違う案内所（DNSサーバー）に道を尋ねに行くよう指示するようなもの。他の人の行き先は変わらない。", "terms": [["--dns", "docker run時に、そのコンテナが利用するDNSサーバーのIPを指定するオプション。"], ["組み込みDNS", "同一ネットワーク内のコンテナ名解決を担うDocker内蔵のDNSサーバー（127.0.0.11）。"]], "think": "コンテナは既定でDockerの組み込みDNS（127.0.0.11）を使い、同じネットワーク内の他コンテナ名や、外部向けにはホストが使うDNSを転送して解決する。--dnsを指定すると、そのコンテナが外部の名前解決に使うDNSサーバーを個別に上書きできる。あくまで指定したコンテナ単位の設定であり、ホスト全体や他のコンテナには影響しない。", "vs": "ホスト全体のDNS設定を書き換えるわけではない。同じネットワーク内のコンテナ名解決（組み込みDNS）自体は引き続き機能する（外部解決先を変えるだけ）。レジストリのpull元アドレスとは無関係。", "usecase": "社内DNSを使わせたい、あるいは特定のパブリックDNS（8.8.8.8等）を使わせたいコンテナだけ個別に設定したいときに使う。", "opt": ["正解。そのコンテナ単位でDNSサーバーを指定する。", "ホスト全体のDNS設定は書き換わらない。", "同じネットワーク内のコンテナ名解決（組み込みDNS）は引き続き機能する。", "レジストリのpull元アドレスとは無関係。"]}'),

  ('dca-q112', 'Security',
   'seccomp・Linuxケーパビリティ・AppArmorの3つの役割の違いとして正しいものはどれか。',
   NULL::text,
   '["seccompは呼べるシステムコールを絞り、ケーパビリティは持てる権限の種類を絞り、AppArmorはファイル・ネットワーク等の操作をプロファイルで制限する", "3つとも同じ仕組みで、どれか1つを設定すれば残り2つは自動的に有効になる", "seccompがファイルアクセス、ケーパビリティがネットワーク、AppArmorがシステムコールをそれぞれ担当する（役割が入れ替わっている）", "3つとも通信の暗号化だけを担当する仕組みで、権限制御には関与しない"]',
   0,
   '[0]',
   'single',
   '{"asked": "3つのセキュリティ機構がそれぞれ異なる層（呼び出し・権限の種類・操作対象）を制限していると理解しているか。", "point": "seccompは『何を呼べるか』、ケーパビリティは『何の権限を持てるか』、AppArmorは『何に対して何ができるか』を制限する。3層は別物。", "kid": "コンテナを守る仕組みは1つではなく、3つの見張り役がそれぞれ違う角度から見ている。seccompは「カーネルへのお願いの種類」を絞り、ケーパビリティは「持てる特別な力」を絞り、AppArmorは「このファイルは読んでよい／このネットワークは使ってよい」のような操作対象そのものを絞る。", "eg": "建物のセキュリティに例えると、seccompは『使ってよいドアの種類』、ケーパビリティは『持てる鍵の種類』、AppArmorは『各部屋で何をしてよいかの規則書』のように、それぞれ違う観点で制限をかけている。", "terms": [["seccomp", "許可されたシステムコール（カーネルへの要求の種類）だけを通すフィルタ。"], ["Linuxケーパビリティ", "root権限を細かく分割した権限の単位（例: NET_BIND_SERVICE）。持たせる分だけ渡す。"], ["AppArmor", "プロセスごとにファイル・ネットワークなどへの操作をプロファイルで制限するアクセス制御（MAC）。"]], "think": "なぜ3層に分かれているのかがカギ。1つの仕組みだけでは防ぎきれない攻撃経路がある。seccompは『そもそもどんな種類の要求をカーネルに送れるか』を絞るので、危険な操作自体を発生させない。ケーパビリティは『権限が細分化されたrootの力』のうち必要な分だけ渡すので、余計な力を封じる。AppArmorはさらに『この実行ファイルはこのパスしか読めない』のように、具体的な操作対象まで踏み込んで制限する。層を重ねることで、1つが破られても他の層が被害を抑える。", "vs": "3つは同じ仕組みではなく、それぞれ独立して設定・有効化される（1つを設定しても他が自動で有効になるわけではない）。役割が入れ替わっているという説明も誤り。通信の暗号化を担当する仕組みでもない（それはTLSなど別領域）。", "usecase": "コンテナのセキュリティを多層防御で固めたいとき、既定のseccomp/capabilitiesに加えてAppArmorプロファイルも組み合わせることで、単一の仕組みの穴を他の層で補える。", "opt": ["正解。3つはそれぞれ違う層（呼び出し・権限の種類・操作対象）を制限する。", "3つは独立した仕組みで、1つの設定が残り2つを自動的に有効にすることはない。", "役割の説明が入れ替わっている。正しい対応はseccomp=システムコール、ケーパビリティ=権限、AppArmor=操作対象。", "通信の暗号化を担当する仕組みではない。"], "viz": "<svg viewBox=\"0 0 340 178\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.3\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">3つの見張り役、それぞれ違う角度で制限</text><rect x=\"20\" y=\"32\" width=\"90\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#60a5fa\" stroke-width=\"1\"/><text x=\"65\" y=\"48\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"600\">seccomp</text><rect x=\"120\" y=\"32\" width=\"200\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"220\" y=\"48\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">何を呼べるか（システムコールの種類）</text><rect x=\"20\" y=\"66\" width=\"90\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"65\" y=\"82\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"600\">capabilities</text><rect x=\"120\" y=\"66\" width=\"200\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"220\" y=\"82\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">何の権限を持てるか（rootを分割した力）</text><rect x=\"20\" y=\"100\" width=\"90\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"65\" y=\"116\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"600\">AppArmor</text><rect x=\"120\" y=\"100\" width=\"200\" height=\"24\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"220\" y=\"116\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">何に対して何ができるか（操作対象そのもの）</text><text x=\"170\" y=\"148\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つが破られても、他の層が被害を抑える</text><text x=\"170\" y=\"161\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">＝多層防御。3つは独立して設定する</text></svg>"}'),

  ('dca-q113', 'Security',
   'docker run --security-opt no-new-privileges myimage の効果として正しいものはどれか。',
   NULL::text,
   '["コンテナ内のプロセスが、setuidバイナリ等を使って起動時より強い権限を後から獲得できないようにする", "コンテナに新しいケーパビリティを一切追加できなくする（--cap-addを禁止する）", "コンテナが新しいネットワークに接続することを禁止する", "コンテナ内で新しいファイルを一切作成できなくする"]',
   0,
   '[0]',
   'single',
   '{"asked": "no-new-privilegesが『実行後の権限昇格』をブロックする設定であり、起動時の権限設定自体を禁止するものではないと理解しているか。", "point": "no-new-privilegesは、プロセスが後から権限を上げる（昇格する）ことをブロックする設定。", "kid": "コンテナの中のプログラムが、動き出したあとにこっそり「もっと強い権限」を手に入れることを防ぐ設定。最初に持っていた権限のまま、それ以上は増やせなくする。", "eg": "入館時に渡された権限カードが、建物の中でこっそり上位カードにグレードアップできないようにする、というイメージ。", "terms": [["no-new-privileges", "プロセスが実行中に権限を昇格できないようにするLinuxカーネルのフラグ。docker runでは --security-opt で有効化する。"], ["setuidバイナリ", "実行すると実行者の権限に関わらず、ファイル所有者（多くはroot）の権限で動くプログラム。悪用されると権限昇格の経路になりうる。"]], "think": "なぜ昇格を防ぐ必要があるのかがカギ。コンテナ内で非rootユーザーとして動かしていても、setuidが付いたバイナリを悪用されると、実行中にroot権限へ昇格されてしまう抜け道が残ることがある。no-new-privilegesを付けると、プロセスがどんな手段を使っても『開始時点の権限より強い権限』を後から得られなくなるため、非rootユーザーで動かす設計（USER命令など）の効果を、実行中も確実に保たせられる。", "vs": "--cap-add自体を禁止するオプションではない（起動時に渡すケーパビリティの設定は別）。ネットワーク接続の禁止やファイル作成の禁止とも無関係。あくまで『実行中の権限昇格』を防ぐ設定。", "usecase": "非rootユーザーで動かすことを前提にしたコンテナで、万一の脆弱性悪用があっても権限昇格までは許さない、という多層防御の一枚として使う。", "opt": ["正解。実行中に権限を後から昇格できないようにする。", "起動時のケーパビリティ設定(--cap-add)自体を禁止する機能ではない。", "ネットワーク接続の禁止とは無関係。", "ファイル作成の禁止とは無関係。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">no-new-privileges：後から強くなれない</text><text x=\"170\" y=\"28\" font-size=\"7\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">setuid等で昇格を試みても</text><rect x=\"20\" y=\"36\" width=\"130\" height=\"26\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"85\" y=\"53\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">開始時の権限</text><line x1=\"150\" y1=\"49\" x2=\"190\" y2=\"49\" stroke=\"#c47070\" stroke-width=\"1.5\"/><rect x=\"190\" y=\"36\" width=\"130\" height=\"26\" rx=\"4\" fill=\"#241a1a\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"255\" y=\"53\" font-size=\"8.5\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"600\">拒否される</text><text x=\"170\" y=\"88\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">非rootで動かす設計(USER命令)の効果を、</text><text x=\"170\" y=\"101\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行中もずっと保証し続けるための一枚</text><text x=\"170\" y=\"124\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">多層防御の1つ。cap-addの禁止とは別物</text></svg>"}'),

  ('dca-q114', 'Security',
   'Docker Content Trust（DCT）の鍵構成における「ルートキー」と「リポジトリキー（タグ付けキー）」の関係として正しいものはどれか。',
   NULL::text,
   '["ルートキーは最上位の信頼の起点で厳重に保管し、リポジトリキーは日常のイメージ署名に使う実務用の鍵", "両方とも同じ鍵で、名前が違うだけ", "リポジトリキーの方がルートキーより強い権限を持ち、ルートキーを無効化できる", "ルートキーは自動的に毎回作り直され、保管する必要がない"]',
   0,
   '[0]',
   'single',
   '{"asked": "DCTの鍵が『滅多に使わない最上位の鍵』と『日常使う実務鍵』に役割分担されていると理解しているか。", "point": "ルートキーは滅多に使わない最上位の信頼の起点、リポジトリキーは日常の署名に使う実務用の鍵。", "kid": "DCTの鍵は1種類ではなく役割分担されている。ルートキーは『すべての信頼の大元』になる特に大事な鍵で普段は使わずしまっておき、リポジトリキーは実際にイメージを push するたびに使う日常用の鍵。", "eg": "会社の実印（ルートキー）は重要な契約のときだけ使い、金庫に厳重にしまっておく。一方、日々の書類には認印（リポジトリキー）を使う、という使い分けに似ている。", "terms": [["ルートキー", "Docker Content Trustの信頼チェーンの最上位に位置する鍵。生成後は普段使わず厳重に保管する。"], ["リポジトリキー（タグ付けキー）", "個別のリポジトリごとに発行され、日常のイメージ署名（push時）に使われる鍵。"]], "think": "なぜ鍵を分けるのかがカギ。もし1つの鍵だけで全てを署名していたら、その鍵が漏れた瞬間に信頼チェーン全体が崩壊する。ルートキーを普段使わない最上位の鍵として厳重に隔離し、日常のpush作業には別のリポジトリキーを使うことで、日常使いの鍵が万一漏れても、ルートキーさえ無事なら被害の範囲を抑えて鍵の失効・再発行で対処できる。", "vs": "同じ鍵ではなく、役割も権限の強さも異なる。リポジトリキーがルートキーより強い権限を持つという説明は逆（ルートキーの方が上位）。ルートキーは自動的に作り直されるものではなく、生成後は厳重に保管し続けるべき鍵。", "usecase": "本番運用でDCTを使う場合、ルートキーはオフラインで厳重に保管し、日々のpushにはリポジトリキーを使うという運用にすることで、漏えいリスクを分散させる。", "opt": ["正解。ルートキーは最上位で厳重保管、リポジトリキーは日常の署名用。", "同じ鍵ではなく、役割も権限も異なる。", "権限の強さの説明が逆。ルートキーの方が上位に位置する。", "ルートキーは自動的に作り直されるものではなく、厳重に保管し続けるべき鍵。"]}'),

  ('dca-q115', 'Security',
   '本番運用前にイメージの脆弱性スキャン（例: docker scout やレジストリ側のスキャン機能）を行う主な目的はどれか。',
   NULL::text,
   '["イメージに含まれるOSパッケージやライブラリの既知の脆弱性（CVE）を、デプロイ前に検知する", "コンテナが実際に動いているときのCPU使用率をリアルタイムに測定する", "イメージのビルドにかかる時間そのものを短縮するための最適化を行う", "Dockerfileの記述に文法的な誤りが無いかどうかを事前に検出する"]',
   0,
   '[0]',
   'single',
   '{"asked": "脆弱性スキャンがイメージの中身（OSパッケージ・ライブラリ）の既知の脆弱性を洗い出す仕組みだと理解しているか。", "point": "脆弱性スキャンは、イメージの中に既知のCVE（脆弱性）を持つパッケージが紛れ込んでいないかをデプロイ前に洗い出す。", "kid": "イメージの中に入っているOSの部品やライブラリを1つ1つ調べて、「これは過去に見つかった弱点（CVE）が報告されているバージョンではないか」をチェックしてくれる仕組み。", "eg": "食品を出荷する前に、材料のロットが過去にリコール対象になっていないか一つ一つ照合するようなもの。", "terms": [["CVE (Common Vulnerabilities and Exposures)", "ソフトウェアの既知の脆弱性に付けられる共通の識別番号。"], ["脆弱性スキャン", "イメージ内のパッケージ一覧を、既知のCVEデータベースと突き合わせてリスクを洗い出す処理。"]], "think": "なぜビルド後にもう一段チェックが要るのかがカギ。Dockerfile自体に文法上の問題が無くても、そこでインストールしているOSパッケージやライブラリのバージョンに、後から脆弱性（CVE）が発覚することがある。脆弱性スキャンは、イメージの中身の一覧（SBOM相当）を作り、それを既知の脆弱性データベースと突き合わせることで、デプロイする前に危険なバージョンが紛れていないかを機械的にチェックする。", "vs": "CPU使用率の測定やビルド時間の短縮とは無関係（それぞれ別の目的のツールの領域）。Dockerfileの構文エラー検出はlintツールの役割で、脆弱性スキャンとは目的が異なる。", "usecase": "CI/CDパイプラインにスキャンを組み込み、重大な脆弱性を含むイメージは自動的にデプロイをブロックする、といった運用に使う。", "opt": ["正解。既知の脆弱性（CVE）を持つパッケージをデプロイ前に検知する。", "CPU使用率の測定とは無関係。", "ビルド時間の短縮とは無関係。", "Dockerfileの構文エラー検出はlintツールの役割で、脆弱性スキャンとは異なる。"]}'),

  ('dca-q116', 'Security',
   'CIS Docker Benchmarkの位置づけとして正しいものはどれか。',
   NULL::text,
   '["Dockerホストやコンテナ設定をどれだけ堅牢化できているか点検するための業界標準チェックリスト", "Dockerが公式に配布している唯一のセキュリティ機能（他のセキュリティ設定は不要になる）", "特定のクラウドベンダーだけが使える専用の監査ツール", "コンテナの起動速度を計測するベンチマークツール"]',
   0,
   '[0]',
   'single',
   '{"asked": "CIS Docker Benchmarkが『機能』ではなく『点検基準（チェックリスト）』であると理解しているか。", "point": "CIS Docker Benchmarkは、設定の堅牢さを点検するための業界標準チェックリストであって、Docker自体の機能ではない。", "kid": "「このDockerの設定はちゃんと安全になっていますか？」を1項目ずつ確認していくための、業界共通のチェックリスト。Dockerというソフトが持っている機能そのものではなく、外側から採点する基準表のようなもの。", "eg": "レストランの衛生検査で使われる共通のチェック項目表のようなもの。店（Dockerホスト）そのものではなく、店を点検するための基準表。", "terms": [["CIS Docker Benchmark", "CIS（Center for Internet Security）が策定する、Dockerホスト・デーモン・コンテナ設定の堅牢化状況を点検するための業界標準チェックリスト。"], ["docker-bench-security", "CIS Docker Benchmarkの項目を自動チェックしてくれる代表的なオープンソースツール。"]], "think": "なぜ『機能』ではなく『基準』なのかがカギ。CIS Docker Benchmarkは、Dockerというソフトウェアの中に組み込まれた機能ではなく、外部の第三者機関が『こう設定していれば安全性が高い』とまとめた点検項目集にすぎない。これに沿って自分の環境を確認する（docker-bench-securityのようなツールで自動化することが多い）ことで、seccompやAppArmor、userns-remapといった個々の機能を『本当にちゃんと有効化できているか』を横断的にチェックできる。", "vs": "唯一のセキュリティ機能というわけではない（seccomp/capabilities/AppArmor/DCTなど個々の機能とは別物で、それらの設定状況を点検する基準）。特定ベンダー専用でもなく、Docker全般に適用できる汎用の基準。起動速度のベンチマークとも無関係。", "usecase": "本番Dockerホストを構築した後、CIS Docker Benchmarkのチェックリスト（またはそれを自動化したツール）で設定の抜け漏れを点検する運用に使う。", "opt": ["正解。設定の堅牢さを点検するための業界標準チェックリスト。", "Docker自体の機能ではなく、個々の機能の設定状況を点検する基準。", "特定ベンダー専用のツールではなく、Docker全般に使える汎用の基準。", "起動速度を計測するベンチマークではない。"]}'),

  ('dca-q117', 'Security',
   'Swarmクラスターのノード間（マネージャー・ワーカー間）の通信について正しい説明はどれか。',
   NULL::text,
   '["既定でTLSにより暗号化・相互認証されており、追加設定なしに保護される", "既定では平文で通信され、暗号化には別途証明書の設定が必要", "ノード間通信はDocker Content Trustによって保護される", "ノード間通信の保護はホストのファイアウォール設定だけに依存する"]',
   0,
   '[0]',
   'single',
   '{"asked": "Swarmのノード間通信が、特別な追加設定なしに既定でTLS保護されていると理解しているか。", "point": "Swarmのノード間通信は既定でTLSにより暗号化・相互認証されている。", "kid": "Swarmのマネージャーとワーカーがやり取りする管理用の通信は、最初から鍵をかけた状態（TLS）で行われる。ユーザーが証明書を用意して設定しなくても、swarm init/joinの時点で自動的に保護される。", "eg": "会社の社内メールが、設定しなくても最初から暗号化されて届く、というイメージ。", "terms": [["Swarmのノード間通信", "マネージャー・ワーカー間でやり取りされる、クラスターの管理情報や状態同期の通信。"], ["自動生成されるTLS証明書", "docker swarm init時にSwarm自身が発行する証明書。ノードの相互認証と通信の暗号化に使われる。"]], "think": "なぜ設定なしで保護されるのかがカギ。docker swarm initを実行すると、Swarm自身が内部的な認証局（CA）の役割を持ち、参加する各ノードに証明書を自動発行する。この証明書を使って、ノード同士が『お互い正規のSwarmメンバーである』ことを相互に確認し合い、通信も暗号化する。これはDocker Content Trust（イメージの署名検証）とは別の仕組みで、Swarm自体の制御プレーンを守るためのもの。", "vs": "既定で平文というのは誤り。証明書はSwarm自身が自動発行するため、利用者が別途証明書を用意する必要は無い。Docker Content Trustはイメージの署名検証の仕組みであり、ノード間通信の保護とは別物。ホストのファイアウォールだけに依存するわけでもない（TLSによる保護がSwarm自体の機能として備わっている）。", "usecase": "Swarmクラスターを構築するだけで、マネージャー・ワーカー間の管理通信が保護されることを前提に設計できる。追加の証明書管理なしに安全な制御プレーンが手に入る。", "opt": ["正解。既定でTLSにより暗号化・相互認証されている。", "既定で平文というのは誤り。Swarm自身が証明書を自動発行して暗号化する。", "Docker Content Trustはイメージ署名の仕組みで、ノード間通信の保護とは別物。", "ファイアウォール設定だけに依存するわけではない。TLSによる保護がSwarm自体の機能として備わっている。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"9.3\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">ノード間通信は最初からTLSで保護済み</text><rect x=\"20\" y=\"32\" width=\"100\" height=\"30\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"70\" y=\"50\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">マネージャー</text><line x1=\"120\" y1=\"47\" x2=\"220\" y2=\"47\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"170\" y=\"41\" font-size=\"7\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">TLSで暗号化・相互認証</text><rect x=\"220\" y=\"32\" width=\"100\" height=\"30\" rx=\"4\" fill=\"#232a1f\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"270\" y=\"50\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ワーカー</text><text x=\"170\" y=\"88\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">swarm init時にSwarm自身が認証局(CA)となり、</text><text x=\"170\" y=\"101\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">各ノードへ証明書を自動発行する</text><text x=\"170\" y=\"124\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">追加設定なしで既定から保護されている</text></svg>"}'),

  ('dca-q118', 'Storage and Volumes',
   'docker volume create --driver local --opt type=nfs --opt o=addr=192.168.1.100,rw --opt device=:/export mynfsvolume の意味として正しいものはどれか。',
   NULL::text,
   '["ローカルドライバーのオプション機能を使って、リモートのNFS共有をボリュームとしてマウントする", "Dockerホストのローカルディスク上に、NFSという名前のフォルダを新規作成するだけ", "リモートのDockerホストへこのボリュームを複製する", "コンテナ内から直接NFSサーバーを起動する"]',
   0,
   '[0]',
   'single',
   '{"asked": "localドライバーが単なる『ホスト内フォルダ』専用ではなく、オプション次第でリモートのNFS等もマウントできると理解しているか。", "point": "localドライバーは--optでtype=nfs等を指定すれば、リモートのNFS共有もボリュームとしてマウントできる。", "kid": "「local」という名前のドライバーだが、オプションの付け方次第で、実は遠くにあるNFSサーバーの共有フォルダをボリュームとして使うこともできる。名前に反して、ホスト内だけに限定された機能ではない。", "eg": "「ローカル郵便局」という名前でも、オプションサービスを使えば海外の倉庫（リモートNFS）にある荷物を直接取り扱えるようになる、というイメージ。", "terms": [["local ドライバー", "Dockerの既定のボリュームドライバー。オプション無指定ならホスト上のディレクトリを使うが、--optでマウントタイプを指定すればNFS等も扱える。"], ["type=nfs", "localドライバーに対して、NFSプロトコルでリモート共有をマウントするよう指示するオプション。"]], "think": "なぜ『local』という名前なのにリモートを扱えるのかがカギ。このドライバーの役割は『Linuxのmountコマンドが理解できる形式でボリュームを用意する』ことであり、mountコマンド自体はNFSやCIFSなどのリモートファイルシステムにも対応している。--opt type=nfsなどでmountコマンドに渡すパラメータを組み立てることで、localドライバー1つで様々なマウント方式に対応できる設計になっている。", "vs": "単なるホスト内フォルダの新規作成ではない（NFSサーバーへの接続を伴う）。リモートホストへのボリューム複製という機能ではない。コンテナ内からNFSサーバーを起動するわけでもない（あくまでクライアントとして接続する）。", "usecase": "複数のDockerホストから同じデータを共有したいとき、外部のNFSサーバーをボリュームとしてマウントし、どのホストのコンテナからでも同じデータにアクセスできるようにする。", "opt": ["正解。オプションでNFS等のリモート共有もボリュームとしてマウントできる。", "単なるホスト内フォルダの新規作成ではなく、NFSサーバーへの接続を伴う。", "リモートホストへのボリューム複製という機能ではない。", "コンテナ内からNFSサーバーを起動する機能ではない。"]}'),

  ('dca-q119', 'Storage and Volumes',
   'docker run -v /host/data:/data:ro myimage のように :ro を付けてバインドマウントした場合の効果はどれか。',
   NULL::text,
   '["コンテナ側からそのマウントパスへは読み取りしかできず、書き込みは拒否される", "ホスト側からそのフォルダへの書き込みも禁止される", ":roを付けても付けなくても動作は変わらない", "コンテナが起動した瞬間、元のホストデータが読み取り専用のコピーに置き換わる"]',
   0,
   '[0]',
   'single',
   '{"asked": ":roがコンテナ視点での読み取り専用マウントであり、ホスト側の権限には影響しないと理解しているか。", "point": ":roを付けると、コンテナ側からそのマウントパスへの書き込みが拒否される。", "kid": "バインドマウントしたフォルダの後ろに「:ro」と書くと、コンテナの中からはそのフォルダを読むことしかできず、書き換えることができなくなる。", "eg": "図書館の本を借りるとき「閲覧のみ・書き込み禁止」の札が付いているようなもの。読むことはできるが、中に書き込むことは許されない。", "terms": [[":ro (read-only)", "バインドマウントやボリュームマウントに付与するオプション。マウント先をコンテナから読み取り専用にする。"]], "think": "なぜコンテナ側だけの制限なのかがカギ。:roはマウントする側（コンテナ）から見た権限を制限するオプションであって、ホスト側のファイルシステム自体の権限を変更するものではない。設定ファイルなど『コンテナには読んでほしいが、うっかり書き換えられたくない』データを渡すときに、コンテナ側のプロセスの誤動作や脆弱性があっても、そのパス経由ではホストのファイルを書き換えられないようにする防御になる。", "vs": "ホスト側から見たそのフォルダへの書き込み可否には影響しない（ホストの他のプロセスは通常通り書き込める）。:roの有無で動作が変わらないというのは誤り（書き込みの可否という重要な差がある）。データがコピーに置き換わるという動作もしない（同じ実体を読み取り専用で見せているだけ）。", "usecase": "設定ファイルや証明書など、コンテナには参照させたいが改ざんされたくないファイルをマウントするときに:roを付ける。", "opt": ["正解。コンテナ側からの書き込みが拒否される。", "ホスト側からの書き込み可否には影響しない。", ":roの有無で書き込み可否という重要な差が生まれる。", "データがコピーに置き換わる動作はしない。同じ実体を読み取り専用で見せているだけ。"]}'),

  ('dca-q120', 'Storage and Volumes',
   'daemon.json の "data-root" を既定の /var/lib/docker から別のパスに変更する目的として正しいものはどれか。',
   NULL::text,
   '["イメージ・コンテナ・ボリュームなどDockerの全データの保存先を、容量の大きい別ディスクなどへ移動する", "各コンテナが実行中に生成したログファイルだけを選んで、別の保存場所へ移動する", "docker buildがビルド時に探しに行くDockerfileの既定の配置場所を変更する", "docker buildが送信するビルドコンテキストの転送先パスを変更する"]',
   0,
   '[0]',
   'single',
   '{"asked": "data-rootがDockerの全データ（イメージ・コンテナ・ボリューム等）の置き場所そのものを変える設定だと理解しているか。", "point": "data-rootを変えると、Dockerの全データの保存場所そのものを別ディスクなどへ丸ごと移動できる。", "kid": "Dockerがイメージやコンテナ、ボリュームなどを保存しているフォルダ（既定は/var/lib/docker）を、まるごと別の場所に引っ越しさせる設定。容量が足りなくなったときなどに使う。", "eg": "本棚がいっぱいになったので、本棚ごと大きな別部屋へ引っ越すようなもの。", "terms": [["data-root", "daemon.jsonの設定項目。Dockerの全データ（イメージ・コンテナ・ボリューム・ネットワーク情報等）を保存するディレクトリのパスを指定する。既定は/var/lib/docker。"]], "think": "既定のOSルートパーティションは容量が小さく設定されていることが多く、イメージやボリュームが増えるとすぐにディスクが逼迫することがある。data-rootを容量の大きい別ディスク（別パーティションやマウントされたストレージ）に向けることで、Dockerが使うデータ全体をそちらへ丸ごと移動できる。", "vs": "ログファイルだけを移動する設定ではない（それはログドライバー側の設定）。Dockerfileの探索場所の変更でもない（それはビルド時の-fオプションの話）。ビルドコンテキストの送信先とも無関係。", "usecase": "OSのルートパーティションの容量が小さいサーバーで、Dockerのデータ保存先を大容量ディスクへ移したいときに使う。", "opt": ["正解。Dockerの全データの保存先そのものを別のパスへ移動できる。", "ログファイルだけの移動設定ではない。", "Dockerfileの探索場所を変更する設定ではない。", "ビルドコンテキストの送信先とは無関係。"]}'),

  ('dca-q121', 'Storage and Volumes',
   'Docker Desktop（Mac/Windows）でホストのフォルダをバインドマウントした場合、Linuxネイティブ環境と比べてI/O性能がどうなりやすいか。',
   NULL::text,
   '["LinuxKit VMを経由したファイル共有層を通るため、一般にネイティブより遅くなりやすい", "VMを経由する分、常にネイティブより速くなる", "バインドマウントかボリュームかに関わらず、常に全く同じ速度になる", "Mac/WindowsではDockerがバインドマウント自体をサポートしていない"]',
   0,
   '[0]',
   'single',
   '{"asked": "Docker DesktopのVM構成が、バインドマウントのI/O性能に影響を与えることを理解しているか。", "point": "Docker DesktopのバインドマウントはVM経由のファイル共有層を通るため、一般にLinuxネイティブより遅くなりやすい。", "kid": "Mac/Windows上のDocker DesktopはLinuxの小さなVMの中でコンテナを動かしている。ホストのフォルダをバインドマウントすると、VMの外（Mac/Windows側）とVMの中（コンテナ側）を橋渡しするファイル共有の仕組みを経由するため、Linuxで直接動かす場合よりやり取りに時間がかかりやすい。", "eg": "隣の部屋に直接物を渡すのと、いったん窓口（VMのファイル共有層）を経由して渡すのとでは、後者の方がひと手間多く時間がかかる、というイメージ。", "terms": [["LinuxKit VM", "Docker DesktopがMac/Windows上でコンテナを動かすために使う軽量Linux仮想環境。"], ["ファイル共有層", "VMの外（ホストOS）とVMの中（コンテナ）の間でファイルをやり取りするための橋渡しの仕組み。バインドマウントのI/Oはここを経由する。"]], "think": "なぜ遅くなりやすいのかがカギ。Linux上でDockerを直接動かす場合、コンテナはホストのカーネルを直接共有しているため、バインドマウントは単なるファイルシステムの参照にすぎない。しかしMac/WindowsのDocker Desktopでは、コンテナは実際にはVMの中で動いており、ホスト側のフォルダとVMの中は別のファイルシステムに存在する。この間を橋渡しするファイル共有層を、読み書きのたびに経由する必要があるため、余分な手間がかかりネイティブLinuxより遅くなりやすい。", "vs": "VMを経由する分、常にネイティブより速くなるというのは逆。バインドマウントとボリュームで速度が全く同じということもない（一般にボリュームの方が最適化されていることが多い）。Mac/Windowsでバインドマウント自体は普通にサポートされている（サポートしていないというのは誤り）。", "usecase": "Mac/Windows開発環境で大量の小さいファイルへの頻繁なI/O（node_modulesなど）が絡む場合に体感速度が落ちやすいと知っておくと、ボリュームの活用や設定の見直しの判断材料になる。", "opt": ["正解。VM経由のファイル共有層を通るため、一般にネイティブより遅くなりやすい。", "VMを経由する分、常にネイティブより速くなるというのは逆。", "バインドマウントとボリュームで速度が全く同じということはない。", "Mac/Windowsでバインドマウント自体は普通にサポートされている。"], "viz": "<svg viewBox=\"0 0 340 165\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"600\">Docker DesktopのバインドマウントはVMをまたぐ</text><text x=\"170\" y=\"27\" font-size=\"7\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">ファイル共有層を経由</text><rect x=\"15\" y=\"34\" width=\"130\" height=\"26\" rx=\"4\" fill=\"#1a1e29\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"80\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Mac/Windows側</text><line x1=\"145\" y1=\"47\" x2=\"175\" y2=\"47\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><rect x=\"180\" y=\"34\" width=\"145\" height=\"26\" rx=\"4\" fill=\"#20263a\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"252.5\" y=\"51\" font-size=\"7.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">LinuxKit VM内のコンテナ</text><text x=\"170\" y=\"76\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Linuxネイティブはカーネル共有だけで済むが、</text><text x=\"170\" y=\"89\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Mac/WindowsはVMの内外を橋渡しする層を毎回経由する</text><text x=\"170\" y=\"112\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">大量の小さいファイルI/Oでは体感速度が落ちやすい</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'dca'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;